insert into public.themen (id, name, beschreibung) values
  (1, 'Arzttermine', 'Lange Wartezeiten und schwer erreichbare Praxen.'),
  (2, 'Miete', 'Hohe Mieten und schwierige Wohnungssuche.'),
  (3, 'Energiepreise', 'Hohe Kosten für Strom und Heizung.'),
  (4, 'Schule', 'Unterrichtsausfall, fehlende Lehrkräfte und marode Schulgebäude.'),
  (5, 'Arbeitsplätze', 'Unsichere Jobs, Stellenabbau und schwache Wirtschaft.'),
  (6, 'Zuwanderung und Integration', 'Probleme bei Aufnahme, Integration und Rückführung von Zugewanderten.'),
  (7, 'Rente', 'Niedrige Renten und Sorge um die Altersvorsorge.'),
  (8, 'Bus und Bahn', 'Seltene Verbindungen, Ausfälle, Verspätungen und teure Tickets.'),
  (9, 'Sicherheit', 'Opfer von Gewalt, Diebstahl oder Betrug werden – zu Hause, unterwegs oder im Internet – oder sich im Alltag unsicher fühlen.'),
  (10, 'Pflege', 'Pflegeplatz oder Pflegedienst finden, hohe Kosten, überlastete Angehörige.'),
  (11, 'Preise und Löhne', 'Lebensmittel und Dinge des Alltags sind teuer geworden, der Lohn reicht kaum.'),
  (12, 'Straßen und Brücken', 'Kaputte Straßen, gesperrte Brücken, lange Umwege und gefährliche Radwege.'),
  (13, 'Internet und Mobilfunk', 'Langsames Internet zu Hause und Funklöcher unterwegs.'),
  (14, 'Behördengänge', 'Lange Wartezeiten auf Termine und Bescheide, viel Papier, dieselben Angaben immer wieder.'),
  (15, 'Autofahren', 'Teures Tanken, wenige Lademöglichkeiten und teure Elektroautos.'),
  (16, 'Heizungstausch', 'Unsicherheit und hohe Kosten, wenn die Heizung erneuert werden muss oder soll.'),
  (17, 'Kita-Betreuung', 'Familien finden keinen passenden Betreuungsplatz oder erleben, dass die Betreuung zu wenig Personal hat, ausfällt oder zu viel kostet.'),
  (18, 'Hitze und Unwetter', 'Hitzewellen, Starkregen und Hochwasser belasten die Gesundheit und beschädigen Wohnungen und Eigentum.')
insert into public.ursachen (id, thema_id, beschreibung, quelle_url, ebene) values
  (101, 1, 'Zu wenige Hausarztpraxen, besonders auf dem Land: Viele Ärztinnen und Ärzte gehen bald in den Ruhestand, zu wenige lassen sich als Hausarzt nieder', 'https://idw-online.de/de/news769524', 'bund'),
  (102, 1, 'Termine und Wege durch das Gesundheitssystem werden kaum gesteuert; knappes Personal wird nicht gezielt eingesetzt', 'https://www.svr-gesundheit.de/publikationen/gutachten-2024/', 'bund'),
  (103, 1, 'Unterschiedliche Vergütung: Facharztpraxen vergeben Termine bevorzugt an Privatversicherte', 'https://idw-online.de/de/news750098', 'bund'),
  (201, 2, 'Es werden weniger Wohnungen gebaut als gebraucht (Bedarf laut Prognose rund 320.000 pro Jahr)', 'https://www.bbsr.bund.de/BBSR/DE/presse/presseinformationen/2025/wohnungsbedarfsprognose.html', 'bund'),
  (202, 2, 'Mieten bei Neuvermietung liegen rund 43 % über Bestandsmieten, in großen Städten besonders hoch', 'https://www.bbsr.bund.de/BBSR/DE/startseite/topmeldungen/entwicklung-wohnungsmieten-2025.html', 'bund'),
  (203, 2, 'Stark gestiegene Baukosten: Wohngebäude wurden 2010 bis 2025 um 89 % teurer, mehr als doppelt so stark wie die Inflation', 'https://www.destatis.de/DE/Themen/Wirtschaft/Preise/Baupreise-Immobilienpreisindex/_inhalt.html', 'bund'),
  (204, 2, 'Mieten in laufenden Verträgen steigen weiter (Nettokaltmieten 2025 im Schnitt +2,1 %)', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2026/01/PD26_019_611.html', 'bund'),
  (205, 2, 'Die Nachfrage wächst vor allem in Großstädten: mehr Haushalte, getragen vor allem von Zuwanderung', 'https://www.iwkoeln.de/fileadmin/user_upload/Studien/Report/PDF/2026/IW-Report_2026-Migration-und-Wohnungsmarkt.pdf', 'bund'),
  (206, 2, 'Jedes Jahr fallen mehr Sozialwohnungen aus der Bindung, als neue gefördert werden (2025: rund 27.000 neu gefördert, rund 55.000 fallen jährlich heraus)', 'https://www.bundestag.de/presse/hib/kurzmeldungen-1200778', 'land'),
  (301, 3, 'Hohe Netzentgelte für den Betrieb und Ausbau der Stromnetze', 'https://www.bundesnetzagentur.de/DE/Vportal/Energie/PreiseAbschlaege/Tarife-table.html', 'bund'),
  (302, 3, 'Steuern, Abgaben und Umlagen machen einen großen Teil der Strom- und Gaspreise aus, beim Gas auch der CO₂-Preis', 'https://www.bundesnetzagentur.de/DE/Vportal/Energie/PreiseAbschlaege/Tarife-table.html', 'bund'),
  (303, 3, 'Rund 70 % der Energie wird importiert, vor allem Öl, Gas und Steinkohle', 'https://www.umweltbundesamt.de/daten/umweltzustand-trends/energie/primaerenergiegewinnung-importe', 'bund'),
  (304, 3, 'Der Strompreis an der Börse richtet sich nach dem teuersten noch benötigten Kraftwerk, heute oft einem Gaskraftwerk', 'https://www.bundestag.de/resource/blob/918822/abb4747668630cbe6d457512d42265c4/WD-5-121-22-pdf-data.pdf', 'bund'),
  (305, 3, 'Drei Viertel der Wohnungen wurden 2022 mit Gas oder Öl beheizt (Zensus); die Heizkosten hängen deshalb stark von deren Preisen ab', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/Zensus2022-Pressemitteilungen/PM_zenus2022_45.html', 'bund'),
  (401, 4, 'Zu wenige Lehrkräfte: Kurzfristig liegt das Angebot deutlich unter dem Einstellungsbedarf', 'https://www.kmk.org/downloads-dokumente/statistik/schulstatistik/lehrkraefteeinstellungsbedarf-und-angebot.html', 'land'),
  (402, 4, 'Großer Sanierungsstau bei Schulgebäuden (rund 68 Mrd. Euro, größter Posten der Kommunen)', 'https://www.bundestag.de/resource/blob/1157306/KfW-Kommunalpanel-2025.pdf', 'land'),
  (403, 4, 'Wachsende Lernrückstände: Ein Drittel der Neuntklässler verfehlt den Mindeststandard in Mathematik', 'https://www.iqb.hu-berlin.de/de/schule/sekundarstufe-i/bildungstrend/2024/', 'land'),
  (404, 4, 'Viele Kinder haben schon vor der Einschulung Sprachförderbedarf; die Länder erfassen und fördern das sehr unterschiedlich', 'https://www.bildungsbericht.de/de/bildungsberichte-seit-2006/bildungsbericht-2024/pdf-dateien-2024/bildungsbericht-2024-kapitel-c.pdf', 'land'),
  (405, 4, 'Der Schulerfolg hängt stark von der sozialen Herkunft ab; sozial benachteiligte Jugendliche fallen seit 2018 weiter zurück', 'https://www.iqb.hu-berlin.de/de/schule/sekundarstufe-i/bildungstrend/2024/', 'land'),
  (501, 5, 'Die Industrie verliert an Wettbewerbsfähigkeit: überdurchschnittlich gestiegene Energiepreise und Lohnstückkosten, dazu hohe wirtschaftspolitische Unsicherheit und geopolitische Veränderungen', 'https://www.sachverstaendigenrat-wirtschaft.de/fileadmin/dateiablage/gutachten/jg202526/JG202526_Kurzfassung.pdf', 'bund'),
  (502, 5, 'Strukturwandel: Die Industrie baut Stellen ab, neue Jobs entstehen vor allem in anderen Branchen', 'https://iab.de/presseinfo/iab-prognose-fuer-2026-2027-erwerbstaetigkeit-schrumpft-trotz-besserer-konjunktur/', 'bund'),
  (503, 5, 'Löhne in Ostdeutschland liegen weiterhin deutlich unter denen im Westen', 'https://www.destatis.de/DE/Themen/Querschnitt/35-Jahre-Deutsche-Einheit/Vermoegen-Einkommen/Textbausteine/01_verdienstunterschiede.html', 'bund'),
  (504, 5, 'Zu wenig Investitionen: Für Verkehr, Bildung, Kommunen und Klimaschutz fehlen über zehn Jahre rund 600 Mrd. Euro zusätzliche öffentliche Investitionen', 'https://www.iwkoeln.de/fileadmin/user_upload/Studien/policy_papers/PDF/2024/IW-Policy-Paper_2024-Investitionsbedarfe.pdf', 'bund'),
  (505, 5, 'Hohe Bürokratiekosten: Unternehmen tragen jährlich rund 64 Mrd. Euro Kosten für Berichts- und Informationspflichten', 'https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Downloads/DE/Jahresberichte/2025-jahresbericht.pdf?__blob=publicationFile&v=5', 'bund'),
  (506, 5, 'Mehr zu arbeiten lohnt sich für Menschen im Bürgergeld oft kaum, weil der Hinzuverdienst größtenteils angerechnet wird', 'https://www.bmas.de/DE/Service/Publikationen/Forschungsberichte/fb-629-erwerbstaetigenfreibetraege.html', 'bund'),
  (507, 5, 'Nur knapp die Hälfte der Beschäftigten (49 %) arbeitet in einem tarifgebundenen Betrieb', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2025/03/PD25_109_623.html', 'bund'),
  (601, 6, 'Zahl der Neuankommenden und Kapazitäten vor Ort passen vielerorts nicht zusammen: Unterbringung bleibt für die meisten Kommunen herausfordernd, Ausländerbehörden sind besonders stark belastet', 'https://mediendienst-integration.de/fileadmin/Dateien/EXPERTISE_FLUECHTLINGSAUFNAHME_IN_DEN_KOMMUNEN_MEDIENDIENST_INTEGRATION_NOV_2025_FINAL.pdf', 'land'),
  (602, 6, 'Asyl- und Gerichtsverfahren dauern lange (im Schnitt rund anderthalb Jahre bis zur rechtskräftigen Entscheidung)', 'https://www.bundestag.de/presse/hib/kurzmeldungen-1145824', 'bund'),
  (603, 6, 'Sprachkurse, Anerkennung von Abschlüssen und Zugang zum Arbeitsmarkt dauern lange', 'https://iab-forum.de/10-jahre-fluchtmigration-2015-was-integration-foerdert-und-was-sie-bremst/', 'bund'),
  (604, 6, 'Viele Ausreisepflichtige werden nicht zurückgeführt, etwa wegen fehlender Papiere', 'https://mediendienst-integration.de/fluechtlinge/abschiebungen/warum-werden-ausreisepflichtige-personen-nicht-abgeschoben/', 'bund'),
  (605, 6, 'Die EU-Zuständigkeitsregeln (Dublin) greifen kaum: 2025 wurde nur rund jede siebte von Deutschland beantragte Überstellung vollzogen', 'https://www.bundestag.de/presse/hib/kurzmeldungen-1161094', 'bund'),
  (606, 6, 'Viele Menschen leben jahrelang nur geduldet: Rund 41 % der gut 180.000 Geduldeten sind seit mehr als fünf Jahren in Deutschland', 'https://mediendienst-integration.de/fluechtlinge/duldung/wie-viele-personen-haben-eine-duldung/', 'bund'),
  (701, 7, 'Immer weniger Beitragszahlende je Rentner: Nach geltendem Recht steigt der Beitrag bis 2039 auf 21,2 %, und das Rentenniveau sinkt auf 46,3 %', 'https://www.bundesregierung.de/breg-de/aktuelles/rentenbericht-2025-2394260', 'bund'),
  (702, 7, 'Niedrige Löhne und Lücken im Erwerbsleben (z. B. Arbeitslosigkeit) führen zu niedrigen Rentenansprüchen', 'https://www.diw.de/sixcms/detail.php?id=diw_01.c.402060.de', 'bund'),
  (703, 7, 'Betriebliche und private Zusatzvorsorge erreicht Geringverdienende, Menschen mit Erwerbsunterbrechungen und Beschäftigte kleiner Betriebe deutlich seltener', 'https://www.diw.de/de/diw_01.c.1005367.de/publikationen/wochenberichte/2026_16_1/private_und_betriebliche_altersvorsoge_ist_zwischen_den_einkommensgruppen_ungleich_verbreitet.html', 'bund'),
  (801, 8, 'Rund 21 Millionen Menschen fehlt ein gutes Grundangebot an Bus und Bahn, besonders auf dem Land', 'https://www.agora-verkehrswende.de/aktuelles/oev-atlas-zeigt-grosse-unterschiede-beim-bus-und-bahnangebot', 'land'),
  (802, 8, 'Marodes, überaltertes Schienennetz; laut Bundesrechnungshof steuert der Bund seine Mittel für den Erhalt kaum wirksam', 'https://www.bundesrechnungshof.de/fileadmin/import/SharedDocs/Downloads/DE/Berichte/2025/evaluation-luf-3_volltext-evaluation-luf-3_volltext.pdf', 'bund'),
  (803, 8, 'Zu wenige Bus- und Straßenbahnfahrerinnen und -fahrer; in den nächsten zehn Jahren gehen rund vier von zehn Beschäftigten in Verkehrsberufen in den Ruhestand', 'https://www.kofa.de/daten-und-fakten/studien/fachkraeftereport-juni-2025/', 'land'),
  (804, 8, 'Tickets werden teurer: Das Deutschlandticket kostet seit Januar 2026 63 Euro im Monat; den Preis legen die Länder fest, Bund und Länder zahlen je 1,5 Milliarden Euro im Jahr zu', 'https://www.bundesregierung.de/breg-de/aktuelles/deutschlandticket-2134074', 'land'),
  (901, 9, 'Nachts fühlen sich viele an bestimmten Orten unsicher: 2024 fühlten sich an Bahnhöfen nur 27 % und in Parks nur 23 % sicher', 'https://www.bka.de/DE/Presse/Listenseite_Pressemitteilungen/2026/Presse2026/260420_PM_PKS_SKiD.html', 'land'),
  (902, 9, 'Viele Straftaten haben keine oder späte Folgen: 2025 blieben 42 % unaufgeklärt; Ende 2024 waren 950.900 Ermittlungsverfahren offen, so viele wie nie seit 2014', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2025/10/PD25_360_2421.html', 'land'),
  (903, 9, 'Junge Menschen werden häufiger Opfer von Gewalt: 2024 wurden 8,5 % der 16- und 17-Jährigen Opfer einer Körperverletzung (2020: 3,1 %); 2025 mehr tatverdächtige Kinder bei Gewaltdelikten', 'https://www.bka.de/DE/Presse/Listenseite_Pressemitteilungen/2026/Presse2026/260420_PM_PKS_SKiD.html', 'land'),
  (904, 9, 'Gewalt in Partnerschaft und Familie auf Höchststand: 2024 rund 266.000 Opfer häuslicher Gewalt (+17,8 % in fünf Jahren), 70 % Frauen; Partnerschaftsgewalt wird zu weniger als 5 % angezeigt', 'https://www.bka.de/DE/Presse/Listenseite_Pressemitteilungen/2025/Presse2025/251121_PM_BLB_HG_StraftatengegenFrauen2024.html', 'land'),
  (905, 9, 'Nichtdeutsche sind bei Gewaltdelikten als Tatverdächtige überrepräsentiert (2025: 42,9 %); Gründe laut Forschung: Alter, Geschlecht, Wohnort, Aufenthaltsperspektive, Zuzug 2015/16 – Gewicht umstritten', 'https://www.bka.de/DE/Presse/Listenseite_Pressemitteilungen/2026/Presse2026/260420_PM_PKS_SKiD.html', 'bund'),
  (906, 9, 'Betrug und Datenmissbrauch im Internet treffen viele und werden selten angezeigt: 2023 war fast jede fünfte Person betroffen; 2025 kamen zwei Drittel der Fälle aus dem Ausland oder von unbekanntem Ort', 'https://skid.bka.de/Wichtige_Ergebnisse.html', 'bund'),
  (907, 9, 'Politisch und religiös motivierte Kriminalität auf Höchststand: 2025 rund 85.800 Straftaten, so viele wie nie, darunter rund 4.200 Gewaltdelikte', 'https://www.bka.de/DE/UnsereAufgaben/Deliktsbereiche/PMK/PMKZahlen/PMKZahlen_node.html', 'bund'),
  (908, 9, 'Sexualisierte Gewalt: Die Polizei erfasst deutlich mehr Vergewaltigungen (2025: +9,0 %, seit 2018 rund +72 %), angezeigt werden aber nur rund 6 %', 'https://www.bka.de/DE/Presse/Listenseite_Pressemitteilungen/2026/Presse2026/260420_PM_PKS_SKiD.html', 'land'),
  (909, 9, 'Zugewanderte werden stärker mit Kriminalität verbunden, als es die Daten zeigen: Nennen Fernsehen und Zeitungen bei Gewalttaten die Herkunft, geht es zu über 90 % um ausländische Tatverdächtige (2025)', 'https://mediendienst-integration.de/news/auslaendische-tatverdaechtige-in-deutschen-leitmedien-ueberrepraesentiert/', 'land'),
  (911, 9, 'Unbehandelte schwere psychische Erkrankungen und Suchterkrankungen erhöhen das Risiko für Gewalttaten, besonders zusammen; die meisten Gewalttaten gehen aber nicht darauf zurück', 'https://journals.plos.org/plosmedicine/article?id=10.1371/journal.pmed.1000120', 'bund'),
  (1001, 10, 'Zu wenige Pflegekräfte; bis 2049 fehlen je nach Szenario 280.000 bis 690.000', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2024/01/PD24_033_23_12.html', 'bund'),
  (1002, 10, 'Steigende Eigenanteile im Heim für Pflege, Ausbildung, Unterkunft und Verpflegung (mit Investitionskosten im ersten Jahr im Schnitt 3.364 Euro im Monat)', 'https://www.vdek.com/presse/pressemitteilungen/2026/stationaere-pflege-eigenanteile-juli-2026.html', 'bund'),
  (1003, 10, 'Die Zahl der Pflegebedürftigen steigt stärker als durch die Alterung allein, auch wegen des 2017 weiter gefassten Pflegebedürftigkeitsbegriffs', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2024/12/PD24_478_224.html', 'bund'),
  (1004, 10, 'Pflegende Angehörige tragen die Hauptlast; Entlastungsangebote werden wenig genutzt', 'https://www.zqp.de/thema/entlastung-pflegende/', 'bund'),
  (1005, 10, 'Die Länder fördern die Investitionskosten der Heime kaum; Bewohner zahlen dafür im Schnitt über 500 Euro im Monat', 'https://www.iges.com/kunden/gesundheit/forschungsergebnisse/2024/investitionskosten-von-pflegeeinrichtungen/index_ger.html', 'land'),
  (1101, 11, 'Lebensmittelpreise hängen stark an den Energiekosten in Landwirtschaft, Transport, Lagerung und Dünger; nach dem Preisschub ab 2021 steigen sie mit dem Energiepreisschock 2026 voraussichtlich erneut', 'https://publikationen.bundesbank.de/publikationen-de/berichte-studien/monatsberichte/monatsbericht-juni-2026-998608?article=deutschland-prognose-energiepreisschock-treibt-teuerung-an-und-bremst-die-konjunkturerholung-998836', 'bund'),
  (1102, 11, 'Der Lebensmittelhandel ist stark konzentriert: Vier Handelsgruppen haben rund 87 % des Umsatzes, und die Preisaufschläge in der Lieferkette sind zeitgleich mit der Konzentration gestiegen', 'https://www.monopolkommission.de/fileadmin/monopolkommission/Indexierte_Dateien/PDFs/Sondergutachten/Monopolkommission-Sondergutachten-84-2025-Wettbewerb-in-der-Lebensmittellieferkette.pdf#page=12', 'bund'),
  (1103, 11, 'Die Löhne hielten mit den Preisen lange nicht mit: Die Reallöhne sanken von 2020 bis 2023 und erreichten 2025 erst wieder fast das Niveau von 2019', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2026/02/PD26_068_62321.html', 'bund'),
  (1104, 11, 'Hohe Steuern und Sozialabgaben auf Arbeit: Bei einem alleinstehenden Durchschnittsverdiener gehen 49,3 % der Arbeitskosten an Staat und Sozialversicherung, der zweithöchste Wert in der OECD (2025)', 'https://www.oecd.org/content/dam/oecd/en/publications/reports/2026/04/taxing-wages-2026-country-notes_491a0e97/germany_649f0784/ca03c391-en.pdf', 'bund'),
  (1105, 11, 'Rund 6,3 Millionen Jobs (16 %) liegen im Niedriglohnbereich, vor allem in Gastgewerbe, Landwirtschaft und Kultur (April 2025)', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2025/12/PD25_434_623.html', 'bund'),
  (1201, 12, 'Viele Autobahnbrücken sind marode, ihre Modernisierung liegt weit hinter dem Plan: Bis Ende 2024 war nur 40 % des Vorgesehenen geschafft; der Autobahn GmbH fehlen Personal und Mittel', 'https://www.bundesrechnungshof.de/SharedDocs/Kurzmeldungen/DE/2025/brueckenmodernisierung/kurzmeldung.html', 'bund'),
  (1202, 12, 'Die Kommunen schieben bei Straßen und Verkehrswegen einen Sanierungsstau von rund 54 Mrd. Euro vor sich her', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_897920.html', 'land'),
  (1203, 12, 'Bauvorhaben kommen schleppend voran: Kommunen setzen nur rund zwei Drittel ihrer geplanten Investitionen um; es fehlt Personal, Genehmigung und Vergabe sind aufwendig', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_897920.html', 'land'),
  (1204, 12, 'Radfahren ist gefährlicher geworden: 2025 starben 462 Radfahrende, 20,6 % mehr als 2015, vor allem Ältere auf Pedelecs; Unfallgegner ist meist ein Auto', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2026/04/PD26_N025_461.html', 'land'),
  (1301, 13, 'Glasfaser reicht erst zu rund 43 % der Haushalte (2025); wo sich der Ausbau nicht lohnt, vor allem auf dem Land, braucht es Förderung, die teuer ist und privaten Ausbau teils verdrängt', 'https://www.wik.org/fileadmin/user_upload/Unternehmen/Veroeffentlichungen/Kurzstudien/2026/WIK_Kurzstudie_Anreizwirkung_der_derzeitigen_Gigabitfoerderung_auf_den_eigenwirtschaftlichen_Glasfaserausbau_in_Deutschland.pdf', 'bund'),
  (1302, 13, 'Rund 2 % der Fläche haben gar keinen Mobilfunk mit 4G oder 5G, vor allem in Wäldern, Höhenlagen, Schutz- und Grenzgebieten', 'https://bmds.bund.de/aktuelles/pressemitteilungen/detail/mobilfunkversorgung-uebersicht-zu-weissen-flecken', 'bund'),
  (1401, 14, 'Online-Angebote der Verwaltung sind schwer zu finden und oft nicht durchgängig digital: Digitale Anträge werden nicht schneller bearbeitet, nur 15 % sehen ihre Erwartungen erfüllt (2025)', 'https://initiatived21.de/presse/egovernment-monitor-2025-wie-die-digitale-verwaltung-helfen-kann-staatsvertrauen-zurueckzugewinnen', 'land'),
  (1402, 14, 'Der Verwaltung fehlt Personal: Bis 2030 geht fast ein Drittel der Beschäftigten im öffentlichen Dienst in den Ruhestand', 'https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Downloads/DE/Jahresberichte/2025-jahresbericht.pdf?__blob=publicationFile&v=5#page=35', 'land'),
  (1403, 14, 'Behörden tauschen Daten kaum aus: Register sind nicht vernetzt, Menschen müssen dieselben Angaben und Nachweise immer wieder einreichen', 'https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Downloads/DE/Jahresberichte/2025-jahresbericht.pdf?__blob=publicationFile&v=5#page=55', 'bund'),
  (1404, 14, 'Die Verwaltung ist mit Aufgaben und kleinteiligen Vorschriften überladen: Die Kommunen beklagen einen ungebremsten Aufgabenanstieg und zu viele Detailvorschriften', 'https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Downloads/DE/Jahresberichte/2025-jahresbericht.pdf?__blob=publicationFile&v=5#page=49', 'bund'),
  (1501, 15, 'Der Spritpreis hängt am Weltmarkt für Rohöl: Mit dem Krieg im Iran und der zeitweisen Sperrung der Straße von Hormus stiegen die Preise 2026 binnen Wochen teils um mehr als ein Drittel', 'https://www.monopolkommission.de/fileadmin/monopolkommission/Indexierte_Dateien/PDFs/Policy_Briefs/Monopolkommission-Policy-Brief-16-2026-Tankrabatt.pdf#page=2', 'bund'),
  (1502, 15, 'Steuern und Abgaben machen einen großen Teil des Spritpreises aus: Energiesteuer (65,45 Cent je Liter Benzin, 47,04 Cent Diesel), CO₂-Preis und Mehrwertsteuer', 'https://www.bundestag.de/resource/blob/834634/dfae7d2604f66510d0469c84eee9e6b5/WD-4-030-21-pdf-data.pdf', 'bund'),
  (1503, 15, 'Wenig Wettbewerb bei Raffinerien und Großhandel: Preissenkungen kommen nicht vollständig an der Zapfsäule an, in Deutschland stiegen die Preise 2026 besonders stark', 'https://www.monopolkommission.de/fileadmin/monopolkommission/Indexierte_Dateien/PDFs/Policy_Briefs/Monopolkommission-Policy-Brief-16-2026-Tankrabatt.pdf#page=1', 'bund'),
  (1504, 15, 'Elektroautos sind für viele noch zu teuer: Gut die Hälfte der Haushalte ohne Elektroauto nennt den Preis als Hindernis (2026: 52 %)', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf#page=23', 'bund'),
  (1505, 15, 'Wer in einem Mehrparteienhaus wohnt, kann oft nicht zu Hause laden: Die rund 9 Millionen Stellplätze an 21 Millionen Wohnungen sind bisher nur unzureichend mit Lademöglichkeiten ausgestattet', 'https://www.bmv.de/SharedDocs/DE/Pressemitteilungen/2026/021-schnieder-500-millionen-foerderung-ladeinfrastruktur-mehrfamilienhaeuser.html', 'bund'),
  (1601, 16, 'Viele halten den Umstieg für nicht lohnend oder können ihn nicht bezahlen: 43 % der Interessierten zweifeln an der Wirtschaftlichkeit einer Wärmepumpe, 32 % fehlt das Geld (2026)', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf#page=19', 'bund'),
  (1602, 16, 'Die Regeln für neue Heizungen wurden in wenigen Jahren mehrfach grundlegend geändert (zuletzt Gebäudemodernisierungsgesetz, Juli 2026), dazu kommt ab 2028 ein europäischer CO₂-Preis für Heizöl und Gas', 'https://www.bundesregierung.de/breg-de/aktuelles/neues-gebaeudemodernisierungsgesetz-2430284', 'bund'),
  (1603, 16, 'Viele wissen noch nicht, ob Fernwärme oder ein Wärmenetz kommt: Erst 26 % der Gemeinden haben ihre Wärmeplanung abgeschlossen (Juni 2026)', 'https://www.bbsr.bund.de/BBSR/DE/veroeffentlichungen/analysen-kompakt/2026/ak-09-2026.html', 'land'),
  (1604, 16, 'Mieterinnen und Mieter können über die Heizung nicht entscheiden, tragen aber die Heizkosten: Sie nutzen fast viermal seltener klimafreundliche Technik als Eigenheimbesitzer (15 % zu 59 %)', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf#page=5', 'bund'),
  (1701, 17, 'Der Betreuungsbedarf der Eltern übersteigt das Angebot bei unter Dreijährigen: 2025 wünschten 49,3 % einen Platz, 37,8 % nutzten ein Angebot (Lücke im Westen 12,7, im Osten 5,8 Prozentpunkte)', 'https://www.akjstat.tu-dortmund.de/themen/kindertagesbetreuung-bis-zum-schuleintritt/weiterhin-ungedeckte-platzbedarfe-kindertagesbetreuung-kompakt-ausbaustand-und-bedarf-2025-erschienen', 'land'),
  (1702, 17, 'Das Personal reicht oft nicht für die Kinderzahl: Mehr als jede zweite Kita-Leitung befürchtet, dass Personalmangel gute Betreuung erschwert, fast 80 % nennen Fehlzeiten als Einschränkung (2024)', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1677-gut-ausgebildet-und-gestresst.html', 'land'),
  (1703, 17, 'Der Personalschlüssel liegt oft unter wissenschaftlichen Empfehlungen: 2022 wurden in Ostdeutschland fast 90 % der Kita-Kinder in nicht kindgerecht besetzten Gruppen betreut (Westen: 62 %)', 'https://www.bertelsmann-stiftung.de/de/themen/aktuelle-meldungen/2023/november/mehr-plaetze-und-bessere-qualitaet-in-kitas-bis-2030-wenn-jetzt-entschlossen-gehandelt-wird', 'land'),
  (1704, 17, 'Kitas schließen immer wieder ungeplant: 2023/24 erlebten 43 % der Familien mit Kita-Kindern unerwartete Schließtage, bei rund 13 % summierten sie sich auf mehr als eine Woche im Kita-Jahr', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1730-unerwartete-kita-schliessungen-gehen-mit-verstaerkten-zweifeln-an-der-qualitaet-einher.html', 'land'),
  (1705, 17, 'Viele Eltern sehen bei den Kosten Verbesserungsbedarf: Bei unter Dreijährigen nennen 37 % „viel Bedarf“ bei den Elternbeiträgen, bei Älteren 24 % (Erhebung 2022)', 'https://doi.org/10.36189/DJI202606', 'land'),
  (1801, 18, 'Hitze nimmt zu: Die Zahl der Heißen Tage (mindestens 30 °C) hat sich im Mittel über Deutschland seit den 1950er-Jahren von etwa 4 auf durchschnittlich 12 pro Jahr verdreifacht', 'https://www.dwd.de/DE/klimaumwelt/klimawandel/klimawandel_node.html', 'bund'),
  (1802, 18, 'Hitze fordert Todesopfer: Das RKI schätzt für die Sommer 2023 und 2024 jeweils rund 3.000 hitzebedingte Sterbefälle, vor allem bei Menschen über 75 Jahren', 'https://edoc.rki.de/handle/176904/12682', 'bund'),
  (1803, 18, 'Großstädte heizen sich auf: In heißen Sommern gab es in Berlin bis zu 20 Tropennächte (Bundesmittel 1 bis 1,5), die Innenstadt war über 11 Kelvin wärmer als das Umland', 'https://www.umweltbundesamt.de/monitoring-zur-das/handlungsfelder/bauwesen/bau-i-1_bau-i-2/indikator', 'land'),
  (1804, 18, 'Viel Fläche ist versiegelt: Ende 2018 waren etwa 45,1 % der Siedlungs- und Verkehrsfläche versiegelt, Regenwasser versickert dort kaum und fließt über die Kanalisation direkt in die Gewässer', 'https://www.umweltbundesamt.de/themen/wasser/extremereignisse/hochwasser', 'land'),
  (1805, 18, 'Auch in Überschwemmungsgebieten wird weiter gebaut: Die bebaute Fläche dort wuchs in rund 20 Jahren bis 2021 um rund 100 km² (knapp 13 %), in rund der Hälfte der Gemeinden ist dort bebaut', 'https://www.umweltbundesamt.de/monitoring-zur-das/handlungsfelder/raumplanung/ro-r-6/indikator', 'land'),
  (1806, 18, 'Viele Wohngebäude sind nicht gegen Elementarschäden versichert: 2024 hatten 57 % eine Volldeckung (vorläufig), in Mecklenburg-Vorpommern 37 %, in Sachsen-Anhalt und Berlin 52 %', 'https://www.svr-verbraucherfragen.de/wp-content/uploads/2026/03/Studie_ESV_in_Deutschland.pdf', 'bund')
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (6067, 4, 'Kostenloses Mittagessen in Kitas und Schulen, gemeinsam mit den Ländern', 'Kostenfreies Essen entlastet benachteiligte Familien; Studien finden teils positive, meist kleine Effekte auf Lernen. Finanzierung mit den Ländern ist aufwendig.', 'gemischt', null, 'bund', null, true, null),
  (6068, 4, 'Investitionsprogramm des Bundes für Schulgebäude, ohne genannten Betrag', 'Investitionsmittel setzen direkt am Sanierungsstau an; der Umfang ist nicht beziffert. Der Bund kann Schulbau nur über Finanzhilfen mitfinanzieren.', 'belegt', null, 'bund', null, true, null),
  (6069, 4, 'Verbindliche Sprachstandsfeststellung vor der Einschulung mit Förderpflicht', 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'gemischt', null, 'land', null, true, null),
  (6070, 4, 'Mehr Unterrichtszeit für Deutsch und Mathematik', 'Mehr Unterrichtszeit für Lesen, Schreiben und Rechnen kann Basiskompetenzen stärken; Studien finden Effekte vor allem bei gezielter, gut angeleiteter Übung. Braucht zusätzliche Lehrkräftestunden, die knapp sind.', 'gemischt', null, 'land', null, true, null),
  (6071, 4, 'Mehr Mittel und Personal für Schulen in schwieriger Lage (Sozialindex)', 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'gemischt', null, 'land', null, true, null),
  (6072, 4, 'Verwaltungs-, IT- und Assistenzkräfte an Schulen', 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'gemischt', null, 'land', null, true, null),
  (6073, 4, 'Mehr und praxisnähere Lehramtsausbildung', 'Mehr und praxisnähere Lehramtsausbildung setzt am Lehrkräftemangel an, wirkt aber erst nach Jahren; wie viele zusätzliche Lehrkräfte im Land ankommen, ist offen. Das Land kann seine Hochschulen selbst steuern.', 'gemischt', null, 'land', null, true, null),
  (6074, 4, 'Zulagen, Stipendien oder Verpflichtungen für unterversorgte Regionen und Fächer', 'Zulagen, Stipendien oder Verpflichtungen können Lehrkräfte in unterversorgte Regionen oder Schulen lenken; die Gesamtzahl der Lehrkräfte steigt dadurch kaum. Für das Land finanzierbar, aber mit dauerhaften Kosten.', 'gemischt', null, 'land', null, true, null),
  (6075, 4, 'Seiten- und Quereinstieg mit Qualifizierung', 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'gemischt', null, 'land', null, true, null),
  (6076, 4, 'Schulbauprogramm des Landes ohne genannten Betrag', 'Ein Schulbauprogramm setzt direkt am Sanierungsstau an; wie weit es reicht, hängt von Umfang, Baukapazitäten und Kommunen ab. Das Programm nennt keinen Betrag, die Finanzierung muss das Land im Haushalt sichern.', 'belegt', null, 'land', null, true, null),
  (6077, 4, 'Mehr Sprachförderung in Kitas, ohne Förderpflicht', 'Mehr Sprachförderung in Kitas setzt am Sprachförderbedarf an; ohne verbindliche Feststellung und Förderpflicht erreicht sie nicht sicher alle Kinder mit Bedarf. Das Land ist zuständig.', 'gemischt', null, 'land', null, true, null),
  (6078, 4, 'Schulsozialarbeit ausbauen und dauerhaft finanzieren', 'Schulsozialarbeit unterstützt Kinder in schwierigen Lagen; Wirkungen auf Leistungen sind kaum belegt. Das Land kann die Finanzierung übernehmen.', 'gemischt', null, 'land', null, true, null),
  (6079, 4, 'Längeres gemeinsames Lernen, mehr Gemeinschaftsschulen', 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'offen', null, 'land', null, true, null),
  (6080, 4, 'Ganztagsangebote an Schulen ausbauen', 'Ganztag kann Kinder aus benachteiligten Familien unterstützen, Effekte auf Leistungen hängen laut Studien stark von der Qualität ab. Der Ausbau braucht Personal und Räume.', 'gemischt', null, 'land', null, true, null),
  (6081, 4, 'Lehrkräfte im Ruhestand zurückgewinnen', 'Pensionierte Lehrkräfte zurückzugewinnen hilft kurzfristig; erfahrungsgemäß kehren nur wenige zurück, eine dauerhafte Lösung ist es nicht. Für das Land leicht umsetzbar.', 'gemischt', null, 'land', null, true, null),
  (6082, 4, 'Leistungsabhängiger Zugang zum Gymnasium', 'Leistungsabhängige Übergänge ins Gymnasium sollen passgenauer fördern; ob die Schulstruktur die Leistungen verbessert, ist in der Forschung nicht entschieden. Das Land kann es im Schulgesetz regeln.', 'offen', null, 'land', null, true, null),
  (6083, 4, 'Handyverbot an Schulen', 'Ein Handyverbot kann Ablenkung im Unterricht verringern; Studien zu Wirkungen auf Leistungen sind gemischt. Das Land kann es per Erlass oder Gesetz regeln.', 'gemischt', null, 'land', null, true, null),
  (6084, 4, 'Kostenloses Schulessen und Lernmittel aus Landesmitteln', 'Kostenfreies Essen und Lernmittel entlasten benachteiligte Familien; Studien finden teils positive, meist kleine Effekte auf das Lernen. Dauerhafte Kosten für das Land.', 'gemischt', null, 'land', null, true, null),
  (6085, 4, 'Schulsanierung beschleunigen, ohne Umfang und Finanzierung', 'Mehr Tempo bei Schulsanierungen setzt am Sanierungsstau an; das Programm nennt aber weder Umfang noch Finanzierung.', 'gemischt', null, 'land', null, true, null),
  (6086, 4, 'Verbindliches Vorschuljahr mit Sprachbildung', 'Ein verbindliches Vorschuljahr kann Sprachrückstände vor der Einschulung verringern; ohne Feststellung des Förderbedarfs ist die Förderung weniger gezielt. Braucht Fachkräfte in Kitas oder Grundschulen.', 'gemischt', null, 'land', null, true, null),
  (6087, 4, 'Getrennte Sprachklassen vor dem Regelunterricht', 'Getrennte Sprachklassen vor dem Regelunterricht können gezielt Deutsch vermitteln; Studien zu getrenntem und gemeinsamem Unterricht sind gemischt. Braucht zusätzliche Lehrkräfte.', 'gemischt', null, 'land', null, true, null),
  (6088, 4, 'Leichtere Anerkennung ausländischer Lehrkräfte', 'Leichtere Anerkennung ausländischer Lehrkräfte (etwa mit nur einem Fach) erschließt kurzfristig zusätzliche Bewerberinnen und Bewerber; ihre Zahl ist begrenzt, das Sprachniveau bleibt eine Hürde. Das Land ist zuständig.', 'gemischt', null, 'land', null, true, null),
  (6089, 5, 'Stromsteuer und Netzentgelte senken', 'Niedrigere Stromsteuer und Netzentgelte senken direkt die Energiekosten, die der Sachverständigenrat als Grund der Industrieschwäche nennt; allein gleichen sie den Kostenabstand aber nicht aus. Die Gegenfinanzierung ist offen.', 'belegt', null, 'bund', null, true, null),
  (6090, 5, 'Unternehmenssteuern senken', 'Niedrigere Unternehmenssteuern können Investitionen anregen, setzen aber nicht an den vom Sachverständigenrat genannten Gründen (Energiepreise, Lohnstückkosten) an; Studien zur Wirkung sind gemischt. Die Gegenfinanzierung ist offen.', 'gemischt', null, 'bund', null, true, null),
  (6091, 5, 'Bürokratie im nationalen Recht abbauen', 'Systematischer Abbau von Pflichten setzt an den Bürokratiekosten an; bisherige Programme haben die Kosten laut Normenkontrollrat nur langsam gesenkt. Umsetzbar im nationalen Recht.', 'gemischt', null, 'bund', null, true, null),
  (6092, 5, 'Hinzuverdienst in Grundsicherung und Wohngeld weniger anrechnen', 'Geringere Anrechnung von Hinzuverdienst setzt direkt an der Ursache an; das ifo/ZEW-Gutachten für das Arbeitsministerium erwartet mehr Beschäftigung. Die Reform ist Bundesrecht, Kosten und Ausgestaltung sind offen.', 'belegt', null, 'bund', null, true, null),
  (6093, 5, 'Investitionsprämie für Unternehmen', 'Eine Investitionsprämie kann Investitionen vorziehen, setzt aber nicht an den vom Sachverständigenrat genannten Gründen an; Studien finden teils Mitnahmeeffekte. Umsetzbar per Bundesgesetz, Finanzierung offen.', 'gemischt', null, 'bund', null, true, null),
  (6094, 5, 'Mindestlohn auf 15 Euro anheben', 'Ein höherer Mindestlohn hebt die unteren Löhne, von denen im Osten mehr Menschen betroffen sind; Studien zur Erhöhung auf 12 Euro fanden kaum Beschäftigungsverluste. Den Abstand oberhalb des Mindestlohns schließt er nicht. Per Bundesgesetz umsetzbar.', 'belegt', null, 'bund', null, true, null),
  (6095, 5, 'Allgemeinverbindlicherklärung von Tarifverträgen erleichtern', 'Eine erleichterte Allgemeinverbindlicherklärung kann die Tarifbindung ganzer Branchen erhöhen, Tariftreue wirkt nur bei öffentlichen Aufträgen; die Wirkung auf die Tarifquote ist in Studien begrenzt belegt. Per Bundesgesetz umsetzbar.', 'gemischt', null, 'bund', null, true, null),
  (6096, 5, 'Geförderte Weiterbildung beim Wechsel von Beruf oder Branche', 'Geförderte Weiterbildung hilft Beschäftigten beim Wechsel in neue Branchen; Studien zeigen positive, aber je nach Maßnahme sehr unterschiedliche Effekte. Umsetzbar über die Arbeitsförderung, Finanzierung offen.', 'gemischt', null, 'bund', null, true, null),
  (6097, 5, 'Berichtspflichten mit EU-rechtlicher Grundlage abschaffen', 'Wegfall von Berichtspflichten setzt an den Bürokratiekosten an; bisherige Programme haben die Kosten laut Normenkontrollrat nur langsam gesenkt. Ein Teil der genannten Pflichten beruht auf EU-Recht, das Deutschland nicht allein ändern kann.', 'gemischt', null, 'bund', null, true, null),
  (6098, 5, 'Schuldenbremse für Investitionen lockern oder abschaffen', 'Mehr Spielraum für öffentliche Investitionen setzt direkt an der Investitionslücke an. Eine Änderung der Schuldenbremse erfordert eine Grundgesetzänderung mit Zweidrittelmehrheit.', 'belegt', null, 'bund', null, true, null),
  (6099, 6, 'Asylsuchende an den Binnengrenzen zurückweisen', 'Zurückweisungen an den Binnengrenzen können einzelne Einreisen verhindern; seit Mai 2025 betrafen sie nur einige hundert Asylsuchende, eine Wirkung auf die Zugangszahlen ist nicht belegt. Die Vereinbarkeit mit der Dublin-Verordnung ist umstritten (VG Berlin, Juni 2025: im Einzelfall rechtswidrig).', 'gemischt', null, 'bund', null, true, null),
  (6100, 6, 'Familiennachzug zu subsidiär Schutzberechtigten aussetzen', 'Das Aussetzen des Familiennachzugs zu subsidiär Schutzberechtigten senkt die Zahl der Neuankommenden etwas (vorher bis zu 1.000 Visa im Monat), im Verhältnis zu allen Zuzügen aber wenig; an den Kapazitäten vor Ort ändert es nichts. Per Bundesgesetz umsetzbar, 2025 für zwei Jahre beschlossen.', 'gemischt', null, 'bund', null, true, null),
  (6101, 6, 'Anerkennung ausländischer Berufsabschlüsse vereinfachen', 'Einfachere und schnellere Anerkennungsverfahren setzen an einer Hürde an, die das IAB nennt; wie viel schneller es wird, hängt von der Ausgestaltung ab. Für viele reglementierte Berufe sind die Länder zuständig.', 'gemischt', null, 'bund', null, true, null),
  (6102, 6, 'Arbeit parallel zum Sprachkurs (Job-Turbo)', 'Arbeit parallel zum Sprachkurs kann den Einstieg beschleunigen; Studien zeigen, dass frühe Beschäftigung die Integration fördert, die Wirkung des Job-Turbos von 2023 ist aber noch nicht abschließend untersucht. Umsetzbar über die Bundesagentur für Arbeit.', 'gemischt', null, 'bund', null, true, null),
  (6103, 6, 'Mehr Staaten als sichere Herkunftsstaaten einstufen', 'Mehr sichere Herkunftsstaaten beschleunigen die Verfahren für Antragsteller aus diesen Ländern; die Hauptherkunftsländer (Syrien, Afghanistan, Türkei) kommen dafür aber kaum in Frage. Einstufung per Gesetz, beim Asylgrundrecht mit Zustimmung des Bundesrats.', 'gemischt', null, 'bund', null, true, null),
  (6104, 6, 'Rücknahme- und Migrationsabkommen mit Herkunftsstaaten', 'Abkommen mit Herkunftsstaaten setzen an den Haupthindernissen an (fehlende Papiere, fehlende Mitwirkung), die Abschiebungen verhindern und Duldungen verlängern; die Erfahrungen sind je nach Partnerland gemischt. Umsetzbar nur mit Zustimmung der Partnerstaaten.', 'gemischt', null, 'bund', null, true, null),
  (6105, 6, 'Mehr Abschiebungshaft und Ausreisegewahrsam', 'Mehr Haft und Gewahrsam kann verhindern, dass Ausreisepflichtige vor dem Termin untertauchen; die meisten Abschiebungen scheitern aber an fehlenden Papieren oder am Herkunftsstaat. Haft ist verfassungsrechtlich eng begrenzt, Haftplätze stellen überwiegend die Länder.', 'gemischt', null, 'bund', null, true, null),
  (6106, 6, 'Asylverfahren in Drittstaaten außerhalb der EU', 'Asylverfahren außerhalb der EU sollen die Weiterreise nach Europa unattraktiv machen; belegt ist das nicht, bisherige Modelle (Großbritannien–Ruanda, Italien–Albanien) kamen kaum in Gang. Umsetzbar nur mit EU-Regeln und aufnahmebereiten Drittstaaten.', 'offen', null, 'bund', null, true, null),
  (6107, 6, 'Integrations- und Sprachkurse ausbauen', 'Mehr und früher zugängliche Sprach- und Integrationskurse verkürzen Wartezeiten; Studien des IAB zeigen, dass Integrationskurse Sprachkenntnisse und Beschäftigung verbessern. Anerkennung und Arbeitsmarktzugang bleiben davon unberührt. Der Bund finanziert die Kurse bereits.', 'belegt', null, 'bund', null, true, null),
  (6108, 6, 'Bleiberecht für gut integrierte Geduldete (Spurwechsel)', 'Ein Bleiberecht für gut integrierte Geduldete beendet die Kettenduldung direkt; mit dem Chancen-Aufenthaltsrecht von 2022 haben viele Geduldete einen Aufenthaltstitel bekommen. Wer die Bedingungen nicht erfüllt, bleibt geduldet. Per Bundesgesetz umsetzbar.', 'belegt', null, 'bund', null, true, null),
  (6109, 6, 'Verbindliche Verteilung Schutzsuchender in der EU', 'Eine verbindliche Verteilung in der EU würde die Zuständigkeitsfrage anders lösen; ob Asylsuchende dann im zugewiesenen Staat bleiben, ist offen. Umsetzbar nur mit einer Mehrheit der EU-Staaten, die bisher nicht in Sicht ist.', 'offen', null, 'bund', null, true, null),
  (6110, 6, 'Arbeitsverbote für Geflüchtete abschaffen', 'Ein früher Zugang zum Arbeitsmarkt setzt direkt an; Studien zeigen, dass Beschäftigungsverbote die Integration in Arbeit noch Jahre später verzögern. Sprachkurse und Anerkennung bleiben davon unberührt. Per Bundesgesetz umsetzbar.', 'belegt', null, 'bund', null, true, null),
  (6111, 6, 'Straftäter vorrangig abschieben', 'Vorrang für Straftäter setzt Schwerpunkte beim Vollzug, beseitigt aber nicht die Hindernisse (fehlende Papiere, Herkunftsstaaten), an denen Abschiebungen meist scheitern. Den Vollzug steuern die Ausländerbehörden der Länder.', 'gemischt', null, 'bund', null, true, null),
  (6112, 6, 'Mehr Personal für Asylbehörden und Verwaltungsgerichte', 'Mehr Personal und gestraffte Verfahren setzen direkt an der Verfahrensdauer an; beim Bundesamt hat Personalaufbau Rückstände schon abgebaut. Das Bundesamt und das Asylprozessrecht regelt der Bund, das Personal der Verwaltungsgerichte stellen die Länder.', 'gemischt', null, 'bund', null, true, null),
  (6113, 6, 'Bezahlkarte oder Sachleistungen für Asylsuchende (Land)', 'Bezahlkarte und Sachleistungen sollen Anreize senken und Auszahlungen vereinfachen; eine Wirkung auf die Zahl der Neuankommenden ist nicht belegt, an Unterkünften und Ausländerbehörden ändert sich nichts. Die Länder können sie im Rahmen des Asylbewerberleistungsgesetzes selbst einführen.', 'offen', null, 'land', null, true, null),
  (6114, 6, 'Asylsuchende zentral in Landes- oder Großunterkünften unterbringen (Land)', 'Zentrale Unterbringung, etwa bis zum Asylbescheid, entlastet die Kommunen, verlagert den Bedarf an Plätzen aber auf das Land; ob Verfahren und Rückführungen dadurch schneller werden, ist kaum untersucht. Das Land schafft die Plätze, die Wohnpflicht regelt der Bund.', 'offen', null, 'land', null, true, null),
  (6115, 6, 'Ausländerbehörden personell und digital stärken (Land)', 'Setzt direkt an der Überlastung der Ausländerbehörden an; wie viel schneller die Verfahren werden, hängt von Stellen und Digitalisierung ab und ist wenig untersucht. Das Land kann Personal und Digitalisierung mitfinanzieren, braucht dafür aber Geld und Fachkräfte.', 'offen', null, 'land', null, true, null),
  (6116, 6, 'Kommunen und Bezirke für die Aufnahme finanziell stärker ausstatten (Land)', 'Mehr Landesgeld, etwa als Pauschale je Platz oder Person, setzt an der Kapazitätsseite an; Geld allein schafft aber nicht sofort Unterkünfte, Kitaplätze oder Personal, und die Programme nennen meist keinen Umfang. Umsetzbar über den Landeshaushalt.', 'gemischt', null, 'land', null, true, null),
  (6117, 6, 'Auf Bundes- und EU-Ebene auf weniger Zugang dringen (Land)', 'Grenzkontrollen, Zurückweisungen, Familiennachzug oder Asylverfahren an den EU-Außengrenzen kann ein Land nicht selbst regeln, sondern nur über den Bundesrat oder beim Bund darauf hinwirken; die Wirkung solcher Maßnahmen auf die Zugangszahlen ist zudem umstritten.', 'gemischt', null, 'land', null, true, null),
  (6118, 6, 'Geflüchtete dezentral in Wohnungen unterbringen (Land)', 'Wohnungen statt Sammelunterkünften erleichtern das Ankommen und können günstiger sein; zusätzliche Plätze entstehen aber nur, wo Wohnungen frei sind, in angespannten Wohnungsmärkten konkurriert der Bedarf mit anderen Wohnungssuchenden. Das Land kann es über Aufnahmegesetz und Förderung steuern.', 'gemischt', null, 'land', null, true, null),
  (6119, 6, 'Verteilung im Land an der Aufnahmefähigkeit der Kommunen ausrichten (Land)', 'Verteilung nach Leistungsfähigkeit oder Zuzugssperren für überlastete Orte (§ 12a Aufenthaltsgesetz) entlasten einzelne Kommunen, verschieben den Bedarf aber nur im Land; Wohnsitzauflagen können laut Studien die Arbeitsaufnahme verzögern. Das Land kann es selbst regeln.', 'gemischt', null, 'land', null, true, null),
  (6120, 6, 'Aufnahmestopp des Landes', 'Ein Aufnahmestopp würde das Land entlasten, den Bedarf aber auf andere Länder verschieben. Die Länder sind nach dem Asylgesetz verpflichtet, die ihnen zugewiesenen Asylsuchenden aufzunehmen; ein einseitiger Stopp ist rechtlich derzeit nicht umsetzbar.', 'offen', null, 'land', null, true, null),
  (6121, 6, 'Mehr Unterbringungsplätze verbindlich schaffen (Land)', 'Verbindliche Vorgaben für Standorte und die Nutzung leer stehender Gebäude setzen direkt an fehlenden Unterkünften an; Planung und Umbau dauern aber, und gegen einzelne Standorte gibt es oft Widerstand vor Ort. Umsetzbar über Landesrecht und Landeshaushalt.', 'gemischt', null, 'land', null, true, null),
  (6122, 6, 'Vom Bund die volle Übernahme der Unterbringungskosten fordern (Land)', 'Eine volle Kostenübernahme durch den Bund würde Länder und Kommunen finanziell entlasten, schafft aber nicht sofort Plätze; ein Land kann sie nur fordern, entscheiden müssen Bundesregierung und Bundestag.', 'gemischt', null, 'land', null, true, null),
  (6173, 7, 'Rentenniveau gesetzlich bei mindestens 48 Prozent halten', 'Eine Haltelinie verhindert, dass die Renten wegen des steigenden Verhältnisses von Rentnern zu Beitragszahlenden hinter den Löhnen zurückfallen; das Missverhältnis bleibt, die Kosten steigen über Beiträge oder Steuerzuschüsse. Per Bundesgesetz umsetzbar, die dauerhafte Finanzierung ist offen.', 'gemischt', null, 'bund', null, true, null),
  (6174, 7, 'Anreize, über das Rentenalter hinaus zu arbeiten', 'Mehr Weiterarbeit im Rentenalter bringt der Rentenversicherung etwas mehr Beiträge und Steuern; Studien erwarten nur kleine Beschäftigungseffekte, Steuerfreiheit kostet Einnahmen. Per Bundesgesetz umsetzbar.', 'gemischt', null, 'bund', null, true, null),
  (6175, 7, 'Pflicht zur Altersvorsorge für nicht abgesicherte Selbstständige', 'Viele Solo-Selbstständige sorgen kaum vor und sind im Alter häufiger arm; eine Vorsorgepflicht setzt direkt an dieser Lücke an, wirkt aber erst über Jahrzehnte, und Pflichtbeiträge belasten Selbstständige mit geringem Einkommen. Per Bundesgesetz umsetzbar.', 'gemischt', null, 'bund', null, true, null),
  (6176, 7, 'Beamte, Abgeordnete und weitere Gruppen in die gesetzliche Rente einbeziehen', 'Mehr Einzahlende verbessern das Verhältnis zu den Rentnern zunächst, später entstehen aus den Beiträgen aber auch Ansprüche; für Beamte kostet der Übergang Bund und Länder anfangs viel Geld. Per Bundesgesetz möglich, mit langen Übergangszeiten.', 'gemischt', null, 'bund', null, true, null),
  (6177, 7, 'Betriebsrenten stärker fördern und für kleine Betriebe erleichtern', 'Setzt direkt an der geringen Verbreitung von Betriebsrenten an; mehr Förderung und weniger Haftungsrisiken haben die Verbreitung bisher aber nur langsam erhöht, vor allem in kleinen Betrieben und bei Geringverdienenden. Per Bundesgesetz umsetzbar.', 'gemischt', null, 'bund', null, true, null),
  (6178, 7, 'Geförderte private Vorsorge neu ordnen (kostengünstige Depots, gezielte Förderung)', 'Kostengünstige, einfache Produkte und eine Förderung für kleine und mittlere Einkommen setzen an der Lücke bei der Zusatzvorsorge an; ob deutlich mehr Menschen vorsorgen, ist offen, solange die Teilnahme freiwillig bleibt. Per Bundesgesetz umsetzbar.', 'gemischt', null, 'bund', null, true, null),
  (6179, 7, 'Kapitalstock zur Stützung der gesetzlichen Rente', 'Ein Fonds kann den Beitragsanstieg dämpfen, wenn weniger Beitragszahlende auf mehr Rentner kommen; bei den vorgeschlagenen Größenordnungen ist der Effekt klein, die Erträge sind unsicher. Per Bundesgesetz umsetzbar, bei Kreditfinanzierung mit Haushaltsrisiken.', 'gemischt', null, 'bund', null, true, null),
  (6180, 7, 'Grundrente ausbauen, niedrige Rentenansprüche aufwerten', 'Eine stärkere Aufwertung niedriger Ansprüche setzt direkt an niedrigen Renten nach niedrigen Löhnen an; wer große Lücken im Erwerbsleben hat, profitiert oft nicht, die Kosten steigen. Per Bundesgesetz umsetzbar, die Finanzierung ist nicht geklärt.', 'gemischt', null, 'bund', null, true, null),
  (6181, 7, 'Mindestlohn auf mindestens 15 Euro anheben', 'Ein höherer Mindestlohn erhöht die Rentenansprüche von Geringverdienenden; auch mit 15 Euro liegt die Rente nach Lücken im Erwerbsleben oft nahe der Grundsicherung. Per Bundesgesetz umsetzbar, bisher entscheidet die Mindestlohnkommission.', 'gemischt', null, 'bund', null, true, null),
  (6182, 7, 'Nicht beitragsgedeckte Leistungen aus dem Bundeshaushalt finanzieren', 'Verlagert Kosten von den Beitragszahlenden auf die Steuerzahlenden und entlastet die Beiträge; am Verhältnis von Beitragszahlenden zu Rentnern ändert es nichts. Es geht um zweistellige Milliardenbeträge im Jahr, deren Finanzierung offen ist.', 'gemischt', null, 'bund', null, true, null),
  (6223, 10, 'Investitionskosten der Heime nicht mehr den Bewohnern anlasten', 'Die Investitionskosten machen einen spürbaren Teil der Eigenanteile im Heim aus; übernehmen die Länder sie, sinkt die Belastung direkt. Der Bund kann es vorschreiben, zahlen müssten aber die Länder, deren Finanzierung offen ist.', 'gemischt', null, 'bund', null, true, null),
  (6224, 10, 'Private Pflegeversicherung in den Finanzausgleich einbeziehen', 'Ein Ausgleich zwischen sozialer und privater Pflegeversicherung verbreitert die Finanzierung und kann Beiträge oder Eigenanteile entlasten; wie viel davon bei den Eigenanteilen ankommt, hängt von der Verwendung ab. Verfassungsrechtlich umstritten, aber per Bundesgesetz möglich.', 'gemischt', null, 'bund', null, true, null),
  (6225, 10, 'Private und betriebliche Pflegezusatzvorsorge fördern', 'Zusatzversicherungen können künftige Eigenanteile abdecken; bisher haben nur wenige eine, Geringverdienende und heute Pflegebedürftige erreicht die Förderung kaum. Per Bundesgesetz umsetzbar.', 'gemischt', null, 'bund', null, true, null),
  (6226, 10, 'Leistungen für häusliche Pflege zu einem flexiblen Budget bündeln', 'Setzt daran an, dass Entlastungsleistungen wenig genutzt werden, weil sie kompliziert und starr sind; ob ein Budget die Nutzung deutlich erhöht, ist noch wenig untersucht. Per Bundesgesetz umsetzbar, erste Schritte gibt es seit 2025.', 'gemischt', null, 'bund', null, true, null),
  (6227, 10, 'Lohnersatz für pflegende Angehörige, die ihre Arbeitszeit reduzieren', 'Ein Lohnersatz ähnlich dem Elterngeld entlastet pflegende Angehörige finanziell und erleichtert, Beruf und Pflege zu verbinden; die Kosten sind je nach Ausgestaltung hoch, und ob mehr Angehörige die Leistung nutzen als die bisherige Pflegezeit, ist offen.', 'gemischt', null, 'bund', null, true, null),
  (6228, 10, 'Tages-, Nacht- und Kurzzeitpflege sowie Beratung ausbauen', 'Mehr erreichbare Entlastungsangebote und Beratung setzen daran an, dass Angehörige die Hauptlast tragen; die Plätze fehlen aber oft auch wegen fehlender Pflegekräfte. Der Bund kann Leistungen und Förderung erhöhen, Planung und Bau liegen bei Ländern und Trägern.', 'gemischt', null, 'bund', null, true, null),
  (6229, 10, 'Arbeitsbedingungen in der Pflege verbessern (Personalbemessung, verlässliche Dienstpläne, weniger Dokumentation)', 'Bessere Arbeitsbedingungen setzen am wichtigsten Grund an, warum Pflegekräfte den Beruf verlassen oder in Teilzeit gehen; eine verbindliche Personalbemessung braucht aber zunächst mehr Personal. Per Bundesgesetz umsetzbar, die Umsetzung dauert Jahre.', 'gemischt', null, 'bund', null, true, null),
  (6230, 10, 'Ausgestiegene Pflegekräfte zurückgewinnen', 'Befragungen zeigen, dass viele ehemalige Pflegekräfte bei besseren Bedingungen zurückkehren würden; wie viele es tatsächlich tun, hängt davon ab, ob sich die Bedingungen spürbar ändern. Ohne eigene Maßnahmen bleibt es ein Ziel.', 'gemischt', null, 'bund', null, true, null),
  (6231, 10, 'Pflegekräfte im Ausland anwerben, Anerkennung beschleunigen', 'Zuwanderung hat einen großen Teil des Beschäftigungszuwachses in der Pflege getragen; lange Anerkennungsverfahren und Sprachhürden bremsen, und die Anerkennung liegt bei den Ländern. Der Bund kann Verfahren vereinfachen und Anwerbung fördern.', 'gemischt', null, 'bund', null, true, null),
  (6232, 10, 'Mehr Befugnisse und Aufstiegswege für Pflegefachpersonen', 'Mehr Verantwortung und Aufstiegsmöglichkeiten machen den Beruf attraktiver; wie stark das die Zahl der Pflegekräfte erhöht, ist kaum belegt. Per Bundesgesetz umsetzbar, erste Schritte wurden 2025 beschlossen.', 'gemischt', null, 'bund', null, true, null),
  (6233, 10, 'Bessere Bezahlung in der Pflege', 'Höhere Löhne machen den Beruf attraktiver und halten Pflegekräfte; seit der Tarifpflicht von 2022 sind die Löhne deutlich gestiegen, was aber auch die Eigenanteile erhöht hat. Die Refinanzierung ist per Bundesgesetz möglich, die Finanzierung ist offen.', 'gemischt', null, 'bund', null, true, null),
  (6234, 10, 'Prävention und Reha, um Pflegebedürftigkeit hinauszuzögern', 'Prävention und Rehabilitation können Pflegebedürftigkeit bei Einzelnen verzögern; an der Alterung der Bevölkerung ändern sie nichts, und ihre Wirkung auf die Zahl der Pflegebedürftigen ist schwer zu belegen. Per Bundesgesetz umsetzbar.', 'gemischt', null, 'bund', null, true, null),
  (6235, 10, 'Pflegeausbildung verbessern und ausbauen', 'Bessere Ausbildungsbedingungen können mehr Menschen in den Beruf bringen und Abbrüche verringern; die Ausbildung ist seit 2020 bereits vergütet und schulgeldfrei, weitere Effekte sind schwer abzuschätzen. Per Bundesgesetz und mit den Ländern umsetzbar.', 'gemischt', null, 'bund', null, true, null),
  (6447, 10, 'Land übernimmt die Investitionskosten der Heime (Land)', 'Übernimmt das Land die Investitionskosten, sinkt der Eigenanteil im Heim direkt um im Schnitt rund 500 Euro im Monat; Unterkunft, Verpflegung und pflegebedingte Kosten bleiben. Das Land kann es selbst regeln, die Kosten von vielen Millionen Euro im Jahr muss es dauerhaft im Haushalt tragen.', 'gemischt', null, 'land', null, true, null),
  (6448, 10, 'Land beteiligt sich an den Investitionskosten, ohne Umfang (Land)', 'Eine Landesbeteiligung an den Investitionskosten senkt den Eigenanteil; ohne Angabe, wie viel das Land übernimmt, bleibt die Entlastung offen. Das Land kann es selbst regeln.', 'gemischt', null, 'land', null, true, null),
  (6449, 10, 'Landesprogramm für Investitionen und Sanierung von Pflegeeinrichtungen (Land)', 'Fördergeld für Bau und Sanierung dämpft, was Heime als Investitionskosten weitergeben, betrifft aber nur geförderte Einrichtungen und senkt den laufenden Eigenanteil der übrigen Bewohner nicht. Das Land kann ein Programm selbst auflegen.', 'gemischt', null, 'land', null, true, null),
  (6637, 2, 'Mietpreisbremse auslaufen lassen, um Investitionen anzuregen', 'Soll Investitionen anregen; Neubauten sind von der Mietpreisbremse ohnehin ausgenommen, die Wirkung auf den Neubau ist daher gering. Studien finden keinen deutlichen Rückgang des Neubaus durch die Bremse.', 'gemischt', null, 'bund', null, true, null),
  (6638, 2, 'Bundesweiter Mietendeckel', 'Begrenzt Mieten direkt, auch bei Neuvermietung, schafft aber keine neuen Wohnungen; in Berlin sanken 2020/21 die regulierten Mieten, zugleich wurden weniger Wohnungen angeboten. Ob ein bundesweiter Deckel mit Absenkung verfassungsgemäß wäre, ist offen.', 'gemischt', null, 'bund', null, true, null),
  (6639, 2, 'Mietenstopp in angespannten Wohnungsmärkten', 'Stoppt Erhöhungen in laufenden Mietverträgen in angespannten Märkten; schafft keine neuen Wohnungen und kann Instandhaltung und Modernisierung bremsen. Ein Mietenstopp wirft verfassungsrechtliche Fragen auf.', 'gemischt', null, 'bund', null, true, null),
  (6640, 2, 'Bessere steuerliche Abschreibung für den Mietwohnungsbau', 'Steuerliche Anreize können Neubau anstoßen; kostet Steuereinnahmen, und ob die Wohnungen günstig vermietet werden, ist nicht gesichert. Frühere Sonderabschreibungen wirkten vor allem bei ohnehin geplanten Projekten.', 'gemischt', null, 'bund', null, true, null),
  (6641, 2, 'Keine neuen kostentreibenden Baustandards, einfachere Standards und digitale Verfahren', 'Verhindert weitere Kostensteigerungen durch Vorschriften und verkürzt Verfahren; bereits gestiegene Material-, Lohn- und Zinskosten bleiben. Wie viel Standards an den Baukosten ausmachen, ist umstritten.', 'gemischt', null, 'bund', null, true, null),
  (6642, 2, 'Sozialen und gemeinnützigen Wohnungsbau stärker fördern, mit langen Bindungen', 'Schafft preisgebundene Wohnungen für Haushalte mit geringem Einkommen; erfordert erhebliche öffentliche Mittel, der Umfang ist nicht beziffert.', 'belegt', null, 'bund', null, true, null),
  (6645, 2, 'Soziale Wohnraumförderung des Landes fortführen (ohne Ausbau)', 'Hält den Neubau geförderter Wohnungen aufrecht, bremst aber den Rückgang des Bestands nicht, solange mehr Wohnungen aus der Bindung fallen als neu gefördert werden.', 'belegt', null, 'land', null, true, null),
  (6646, 2, 'Soziale Wohnraumförderung des Landes ausbauen, Bundesmittel voll kofinanzieren', 'Mehr geförderte Neubauten wirken dem Rückgang des Bestands direkt entgegen; das Land muss dafür zusätzliche Haushaltsmittel bereitstellen, und die Wirkung hängt davon ab, dass Bauherren die Förderung annehmen.', 'belegt', null, 'land', null, true, null),
  (6647, 2, 'Sozialbindung geförderter Wohnungen unbefristet', 'Verhindert, dass künftig geförderte Wohnungen nach einigen Jahren aus der Bindung fallen; das Land kann das im eigenen Förderrecht regeln. Private Bauherren nehmen eine Förderung mit Dauerbindung womöglich seltener an.', 'gemischt', null, 'land', null, true, null),
  (6648, 2, 'Höhere Quote für Sozialwohnungen bei Neubauten (kooperative Baulandentwicklung)', 'Sichert in neuen Quartieren mehr Sozialwohnungen ohne volle Landesförderung; eine sehr hohe Quote kann private Bauvorhaben unwirtschaftlich machen und den Neubau bremsen.', 'gemischt', null, 'land', null, true, null),
  (6649, 2, 'Fehlbelegungsabgabe für Mieter in Sozialwohnungen mit gestiegenem Einkommen', 'Lenkt Sozialwohnungen stärker zu Bedürftigen und bringt Geld für neue Förderung; schafft selbst kaum neue Wohnungen, der Verwaltungsaufwand ist hoch, und Besserverdienende ziehen aus, was die Durchmischung verringern kann.', 'gemischt', null, 'land', null, true, null),
  (6650, 2, 'Große Vermieter per Landesgesetz verpflichten, einen Teil der Wohnungen an WBS-Haushalte zu vermieten', 'Würde den Bestand an Wohnungen für Haushalte mit geringem Einkommen schnell erweitern; ob ein Land das regeln darf, ist fraglich, denn das Mietrecht ist Bundessache (Bundesverfassungsgericht 2021 zum Berliner Mietendeckel).', 'offen', null, 'land', null, true, null),
  (6677, 1, 'Hausarztpraxis als erste Anlaufstelle (Primärarztsystem)', 'Lenkt Patientinnen und Patienten gezielter und kann unnötige Facharztbesuche vermeiden; die Erfahrungen aus Ländern mit Primärarztsystem sind überwiegend positiv. Es setzt aber voraus, dass genug Hausarztpraxen da sind, die schon heute knapp sind.', 'gemischt', null, 'bund', null, true, null),
  (6678, 1, 'Andere Gesundheitsberufe übernehmen mehr Aufgaben (z. B. Advanced Practice Nurses, Gemeindeschwestern)', 'Entlastet Ärztinnen und Ärzte, sodass mehr Termine frei werden; internationale Studien zeigen gute Qualität bei übertragenen Aufgaben. Braucht neue Ausbildungswege und Änderungen im Berufsrecht, das dauert.', 'belegt', null, 'bund', null, true, null),
  (6679, 1, 'Kommunale MVZ und Gesundheitszentren fördern', 'Angestelltenverhältnisse und Teamarbeit entsprechen den Wünschen vieler junger Ärztinnen und Ärzte und können Praxissitze in unterversorgten Regionen besetzen; wie viele Zentren tatsächlich entstehen, hängt von Kommunen und Finanzierung ab.', 'gemischt', null, 'bund', null, true, null),
  (6680, 1, 'Budgetierung ärztlicher Leistungen aufheben', 'Voll bezahlte Leistungen machen Kassenpatienten für Praxen attraktiver und verringern den Vergütungsabstand zu Privatversicherten; ob dadurch spürbar mehr Termine entstehen, ist nicht belegt, und die Mehrkosten tragen die Beitragszahlenden.', 'gemischt', null, 'bund', null, true, null),
  (6681, 1, 'Einheitliche Vergütung für gesetzlich und privat Versicherte (Bürgerversicherung)', 'Nimmt Praxen den finanziellen Anreiz, Privatversicherte bei Terminen vorzuziehen; ob die Wartezeiten insgesamt sinken, hängt von der Höhe der neuen Vergütung ab. Der Umbau der privaten Krankenversicherung ist rechtlich und praktisch sehr aufwendig.', 'gemischt', null, 'bund', null, true, null),
  (6703, 3, 'Netzentgelte mit Bundesmitteln senken oder deckeln', 'Senkt einen großen Teil des Strompreises direkt und spürbar; die Kosten des Netzausbaus trägt dann der Bundeshaushalt, und die Finanzierung muss auf Dauer gesichert werden.', 'belegt', null, 'bund', null, true, null),
  (6704, 3, 'Stromsteuer für alle auf das EU-Mindestmaß senken', 'Senkt den Strompreis für Haushalte um gut 2 Cent je Kilowattstunde; kostet den Bundeshaushalt mehrere Milliarden Euro im Jahr.', 'belegt', null, 'bund', null, true, null),
  (6705, 3, 'Klimageld: Einnahmen aus dem CO₂-Preis pro Kopf an die Haushalte zurückgeben', 'Gleicht höhere Heizkosten durch den CO₂-Preis vor allem für Haushalte mit geringem Einkommen aus, senkt die Preise selbst aber nicht; ein Auszahlungsweg muss erst aufgebaut werden.', 'belegt', null, 'bund', null, true, null),
  (6706, 3, 'CO₂-Preis auf Heizen abschaffen', 'Würde Gas- und Heizölpreise direkt senken; ab 2028 gilt aber der europäische Emissionshandel für Gebäude und Verkehr, den Deutschland nicht allein abschaffen kann.', 'belegt', null, 'bund', null, true, null),
  (6707, 3, 'Erneuerbare Energien und Speicher schneller ausbauen', 'Mehr Wind- und Solarstrom verdrängt teure Gaskraftwerke an der Börse und senkt dort die Preise; zugleich kostet der dafür nötige Netzausbau Geld, das über die Netzentgelte bezahlt wird.', 'gemischt', null, 'bund', null, true, null),
  (6708, 3, 'Kohle- und Kernkraftwerke länger oder wieder betreiben', 'Mehr Kraftwerksleistung könnte die Börsenpreise in einzelnen Stunden senken; die abgeschalteten Kernkraftwerke sind weitgehend zurückgebaut, eine Wiederinbetriebnahme wäre teuer, langwierig und rechtlich neu zu regeln, und Kohlestrom wird durch den Emissionshandel teurer.', 'gemischt', null, 'bund', null, true, null),
  (6709, 3, 'Dynamische Stromtarife und intelligente Messsysteme', 'Haushalte, die Strom in günstigen Stunden nutzen können, sparen; für viele Haushalte ohne Wärmepumpe, E-Auto oder Batterie ist die Ersparnis gering.', 'gemischt', null, 'bund', null, true, null),
  (6740, 8, 'Mehr Bundesmittel für den Nahverkehr (Regionalisierungsmittel)', 'Mehr Geld erlaubt den Ländern, mehr Züge und Busse zu bestellen; ob es beim Angebot auf dem Land ankommt oder etwa für gestiegene Kosten oder Ticketpreise gebraucht wird, entscheiden die Länder.', 'gemischt', null, 'bund', null, true, null),
  (6741, 8, 'Netz und Betrieb der Deutschen Bahn stärker trennen', 'Soll Wettbewerb und klare Verantwortung für das Netz schaffen; in anderen Ländern hat die Trennung nicht einheitlich zu einem besseren Netz geführt, und die Umstrukturierung bindet Jahre.', 'gemischt', null, 'bund', null, true, null),
  (6742, 8, 'Überjährige Finanzierung der Schiene über einen Fonds', 'Verlässliche Mittel über mehrere Jahre erleichtern die Planung von Sanierungen, wie der Bahninfrastrukturfonds der Schweiz zeigt; ohne bessere Steuerung ist nicht gesichert, dass mehr Geld den Zustand verbessert.', 'gemischt', null, 'bund', null, true, null),
  (6743, 8, 'Busführerschein und Berufskraftfahrerqualifikation günstiger und einfacher', 'Senkt eine Hürde für den Berufseinstieg; die Regeln stammen zum großen Teil aus EU-Richtlinien, und Bezahlung und Arbeitszeiten bleiben die Hauptgründe für den Mangel.', 'gemischt', null, 'bund', null, true, null),
  (6744, 8, 'Schienennetz mit mehr Mitteln sanieren und ausbauen', 'Setzt direkt am maroden Netz an, wirkt wegen Bauzeiten aber erst nach Jahren; der Bundesrechnungshof bezweifelt, dass mehr Mittel ohne bessere Steuerung den Zustand verbessern.', 'gemischt', null, 'bund', null, true, null),
  (6745, 8, 'Bund steuert die Infrastruktur der Deutschen Bahn wirksamer', 'Setzt an der vom Bundesrechnungshof kritisierten Steuerung an; wie viel das für Pünktlichkeit bringt, ist kaum untersucht.', 'offen', null, 'bund', null, true, null),
  (6746, 8, 'Bessere Bezahlung und Arbeitsbedingungen im Nahverkehr (Tariftreue, Personalübernahme)', 'Bessere Bedingungen machen den Fahrdienst attraktiver und halten Beschäftigte im Beruf; die Kosten tragen Länder und Kommunen, und Vergaben regeln vor allem die Länder.', 'gemischt', null, 'bund', null, true, null),
  (6747, 8, 'Stillgelegte Bahnstrecken reaktivieren', 'Verbessert die Anbindung einzelner ländlicher Orte deutlich, erreicht insgesamt aber nur wenige Menschen; Planung und Bau dauern viele Jahre.', 'gemischt', null, 'bund', null, true, null),
  (6748, 8, 'Verbindliches Mindestangebot an Bus und Bahn (Mobilitätsgarantie)', 'Setzt direkt am fehlenden Grundangebot an; ein flächendeckender Takt ist teuer und scheitert derzeit auch am fehlenden Fahrpersonal. Zuständig sind die Länder, der Bund kann über Geld und Rahmenrecht beitragen.', 'offen', null, 'bund', null, true, null),
  (6749, 8, 'Landesweites Bus- und Bahnnetz ausbauen, Takte verdichten', 'Häufigere Fahrten und direkte Verbindungen verbessern das Angebot spürbar und ziehen mehr Fahrgäste an; das Land muss die zusätzlichen Fahrten dauerhaft bezahlen und braucht Fahrpersonal.', 'belegt', null, 'land', null, true, null),
  (6750, 8, 'Rufbusse und On-Demand-Verkehre ausbauen', 'Schließt Lücken dort, wo Linienbusse fast leer fahren würden; Rufbusse befördern wenige Menschen je Fahrt und sind teuer, ersetzen also keinen dichten Takt.', 'gemischt', null, 'land', null, true, null),
  (6751, 8, 'Verbindliches Mindestangebot (z. B. Stundentakt für jeden Ort, 10-Minuten-Takt in der Stadt)', 'Setzt direkt am fehlenden Grundangebot an; ein flächendeckender Takt ist teuer und braucht Fahrpersonal, das derzeit fehlt.', 'offen', null, 'land', null, true, null),
  (6752, 8, 'Stillgelegte Strecken und Haltepunkte reaktivieren (Land)', 'Verbessert die Anbindung einzelner Orte deutlich, erreicht insgesamt aber wenige Menschen; Planung und Bau dauern Jahre.', 'gemischt', null, 'land', null, true, null),
  (6753, 8, 'Tariftreue und bessere Bezahlung im Nahverkehr (Land)', 'Bessere Bezahlung macht den Fahrdienst attraktiver und hält Beschäftigte; das Land kann Tariftreue in der Vergabe und bei eigenen Unternehmen durchsetzen, muss die Mehrkosten aber tragen.', 'gemischt', null, 'land', null, true, null),
  (6754, 8, 'Offensive zur Gewinnung und Ausbildung von Fahrpersonal', 'Schnellere Qualifizierung, Anerkennung ausländischer Abschlüsse und eigene Ausbildung setzen direkt am Mangel an; ohne bessere Bedingungen verlassen viele den Beruf wieder.', 'gemischt', null, 'land', null, true, null),
  (6824, 1, 'Mehr Studienplätze in der Medizin', 'Mehr Absolventinnen und Absolventen setzen am Nachwuchsmangel an, wirken aber erst nach etwa zwölf Jahren Studium und Weiterbildung; ob sie Hausärzte auf dem Land werden, ist offen. Studienplätze finanzieren die Länder, der Bund kann nur mitfinanzieren.', 'gemischt', null, 'bund', null, true, null),
  (6828, 3, 'Wieder Gas aus Russland über Nord Stream beziehen', 'Mehr Pipelinegas könnte den Gaspreis senken, würde die Abhängigkeit von einem einzelnen Lieferland aber wieder erhöhen; die EU hat mit der Verordnung (EU) 2026/261 die Einfuhr von russischem Gas verboten (Pipelinegas spätestens ab Herbst 2027), eine Wiederaufnahme wäre EU-rechtswidrig.', 'gemischt', null, 'bund', null, true, null),
  (6837, 8, 'Deutschlandticket günstiger machen (Bund gemeinsam mit den Ländern)', 'Ein niedrigerer Preis entlastet alle Fahrgäste direkt; das Neun-Euro-Ticket und die Einführung des Deutschlandtickets haben die Nutzung deutlich erhöht. Jeder Euro weniger kostet Bund und Länder Hunderte Millionen im Jahr, den Preis legen die Länder fest.', 'belegt', null, 'bund', null, true, null),
  (6838, 8, 'Vergünstigtes Deutschlandticket für bestimmte Gruppen (Bund)', 'Entlastet Gruppen mit wenig Geld wie Auszubildende, Studierende oder Menschen mit geringem Einkommen gezielt; für alle anderen ändert sich nichts. Der Bund kann es nur gemeinsam mit den Ländern einführen und mitfinanzieren.', 'belegt', null, 'bund', null, true, null),
  (6839, 8, 'Deutschlandticket mit Landesmitteln erhalten', 'Sichert den bundesweit einheitlichen Preis, verhindert aber weitere Preiserhöhungen nicht; das Land zahlt seinen Anteil schon heute.', 'belegt', null, 'land', null, true, null),
  (6840, 8, 'Vergünstigte Tickets für bestimmte Gruppen (Sozial-, Senioren-, Azubi-, Schülerticket)', 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'belegt', null, 'land', null, true, null),
  (6841, 8, 'Kostenloser Nahverkehr für junge Menschen (Schüler, Auszubildende, unter 21 oder 27 Jahren)', 'Nimmt jungen Menschen die Kosten ganz ab; kostenlose Schülertickets gibt es in mehreren Ländern bereits. Das Land muss die Einnahmeausfälle dauerhaft ausgleichen.', 'belegt', null, 'land', null, true, null),
  (6879, 11, 'Mehrwertsteuer auf Lebensmittel senken (von 7 auf 5 %)', 'Senkt die Preise einmalig um knapp 2 %, wenn der Handel die Senkung weitergibt; an den Ursachen der Preissteigerung ändert das nichts. Rechtlich und finanziell ohne große Hürden möglich.', 'gemischt', null, 'bund', null, true, null),
  (6880, 11, 'Mehrwertsteuer auf Grundnahrungsmittel abschaffen (0 %)', 'Senkt die Preise für Grundnahrungsmittel um bis zu 6,5 % und entlastet vor allem Haushalte mit wenig Geld, wenn die Senkung weitergegeben wird; seit 2022 erlaubt das EU-Recht einen Nullsatz. Dagegen spricht der hohe Steuerausfall, und ob der Handel die Senkung vollständig weitergibt, ist umstritten.', 'gemischt', null, 'bund', null, true, null),
  (6881, 11, 'Preisbeobachtung oder Preisüberwacher für Lebensmittel', 'Macht Preise und Margen entlang der Lieferkette sichtbar und kann Kartellverfahren anstoßen; ob Transparenz allein die Preise senkt, ist kaum untersucht.', 'offen', null, 'bund', null, true, null),
  (6882, 11, 'Marktbeherrschende Handelskonzerne entflechten', 'Setzt an der Konzentration im Lebensmittelhandel an; ob kleinere Händler niedrigere Preise bringen, ist offen. Eine Entflechtung ohne Rechtsverstoß ist verfassungsrechtlich umstritten und dauert Jahre.', 'gemischt', null, 'bund', null, true, null),
  (6883, 11, 'Fusionskontrolle und Wettbewerbsrecht stärken', 'Kann weitere Konzentration im Handel bremsen, wie es die Monopolkommission empfiehlt; auf die Preise wirkt das erst langfristig und nicht sicher.', 'gemischt', 'https://www.monopolkommission.de/publikationen/lebensmittel/s/wettbewerb-in-der-lebensmittellieferkette', 'bund', null, true, null),
  (6884, 11, 'Einkommensteuer für kleine und mittlere Einkommen senken, gegenfinanziert', 'Erhöht das Nettoeinkommen von Geringverdienenden und der Mitte direkt; die Gegenfinanzierung über höhere Steuern für hohe Einkommen oder Vermögen ist umsetzbar, aber politisch und rechtlich aufwendig.', 'belegt', null, 'bund', null, true, null),
  (6885, 11, 'Einkommensteuertarif abflachen und Grundfreibetrag erhöhen', 'Erhöht das Nettoeinkommen fast aller Steuerzahlenden, am stärksten in absoluten Beträgen bei höheren Einkommen; die Kosten sind hoch und die Finanzierung ist nicht geklärt.', 'belegt', null, 'bund', null, true, null),
  (6886, 11, 'Grundfreibetrag stark anheben (auf rund 15.000 Euro bzw. die Armutsgefährdungsschwelle)', 'Entlastet besonders kleine Einkommen spürbar; die Steuerausfälle lägen im hohen zweistelligen Milliardenbereich, eine Finanzierung ist nicht geklärt.', 'belegt', null, 'bund', null, true, null),
  (6887, 11, 'Sozialabgaben bei 40 % begrenzen', 'Verhindert weitere Beitragssteigerungen, senkt die Abgaben aber nicht; dafür wären Reformen in Rente, Gesundheit und Pflege nötig, die noch offen sind.', 'gemischt', null, 'bund', null, true, null),
  (6888, 11, 'Beiträge für Bürgergeldbeziehende aus Steuern statt aus Beiträgen finanzieren', 'Senkt die Kranken- und Pflegebeiträge etwas, weil der Bund die Kosten trägt; die Entlastung der Beschäftigten ist gering und belastet den Bundeshaushalt mit rund zehn Milliarden Euro im Jahr.', 'gemischt', null, 'bund', null, true, null),
  (6889, 11, 'Mindestlohn auf 15 Euro oder 60 % des Medianlohns anheben', 'Erhöht die Löhne im Niedriglohnbereich direkt; Studien zur Einführung 2015 und zur Erhöhung 2022 fanden kaum Jobverluste. Der Bundestag kann die Höhe per Gesetz festlegen, wie 2022 geschehen.', 'belegt', null, 'bund', null, true, null),
  (6890, 11, 'Tarifbindung stärken (Tariftreuegesetz, Allgemeinverbindlichkeit erleichtern)', 'Wer nach Tarif arbeitet, verdient im Schnitt mehr; Tariftreue greift aber nur bei öffentlichen Aufträgen, und wie stark die Tarifbindung dadurch steigt, ist offen.', 'gemischt', null, 'bund', null, true, null),
  (6891, 11, 'Minijobs in sozialversicherungspflichtige Beschäftigung überführen', 'Minijobs sind überwiegend schlecht bezahlt; ob ihre Umwandlung zu höheren Stundenlöhnen führt oder nur zu mehr Sozialversicherung bei gleichem Netto, ist umstritten.', 'gemischt', null, 'bund', null, true, null),
  (6892, 11, 'Steuerermäßigung für Agrardiesel wieder einführen', 'Senkt die Energiekosten landwirtschaftlicher Betriebe um wenige Hundert Millionen Euro im Jahr; auf die Lebensmittelpreise wirkt das kaum.', 'offen', null, 'bund', null, true, null),
  (6929, 12, 'Erhalt und Sanierung von Autobahnen, Straßen und Brücken ausreichend und verlässlich finanzieren', 'Mehr und planbares Geld ist eine Voraussetzung, um den Rückstand bei den Brücken aufzuholen; laut Bundesrechnungshof fehlen der Autobahn GmbH aber auch Personal und Steuerung. Seit 2025 steht mit dem Sondervermögen Infrastruktur zusätzliches Geld bereit.', 'gemischt', 'https://www.bundesrechnungshof.de/SharedDocs/Pressemitteilungen/DE/2025/brueckenmodernisierung.html', 'bund', null, true, null),
  (6930, 12, 'Vorrang für Sanierung vor Neu- und Ausbau von Straßen', 'Bündelt knappe Planungs- und Baukapazitäten auf den Erhalt, wie es der Bundesrechnungshof für die Brücken fordert; weniger Neubau kann Engpässe auf überlasteten Strecken länger bestehen lassen.', 'gemischt', 'https://www.bundesrechnungshof.de/SharedDocs/Statements/DE/2025/brueckenmodernisierung.html', 'bund', null, true, null),
  (6931, 12, 'Großes Investitionsprogramm, Investitionen von der Schuldenbremse ausnehmen', 'Mehr Geld für Bund, Länder und Kommunen kann Sanierungsstau abbauen; ob es bei Straßen und Brücken ankommt und verbaut werden kann, hängt von Personal und Verfahren ab. Braucht eine Grundgesetzänderung, wie sie 2025 für das Sondervermögen beschlossen wurde.', 'gemischt', null, 'bund', null, true, null),
  (6932, 12, 'Finanzierungskreislauf Straße: Lkw-Maut für die Autobahn GmbH, privates Kapital', 'Macht die Finanzierung der Autobahnen planbarer und unabhängiger vom Haushalt; öffentlich-private Partnerschaften waren laut Bundesrechnungshof bisher oft teurer als konventionelle Vergabe.', 'gemischt', null, 'bund', null, true, null),
  (6933, 12, 'Planung und Genehmigung beschleunigen, Ersatzneubauten ohne Planfeststellung oder Umweltprüfung', 'Verkürzt die Zeit bis zum Ersatz maroder Brücken, bei denen sich an Lage und Umweltwirkung wenig ändert; seit 2023 gibt es dafür schon Erleichterungen. Nach Bundesrechnungshof und KfW bremsen vor allem Personal und Geld, nicht nur die Verfahren.', 'gemischt', null, 'bund', null, true, null),
  (6934, 12, 'Kommunalfinanzen stärken: Altschuldenlösung, Gemeindefinanzreform', 'Gibt überschuldeten Kommunen wieder Spielraum für Investitionen; ob das Geld in Straßen fließt, entscheiden die Kommunen. Eine Altschuldenlösung braucht eine Einigung von Bund und Ländern.', 'gemischt', null, 'bund', null, true, null),
  (6935, 12, 'Güterverkehr von der Straße auf die Schiene verlagern', 'Schwere Lkw belasten Brücken am stärksten, weniger Lkw verlangsamen den Verschleiß; eine spürbare Verlagerung braucht aber Jahre und mehr Kapazität auf der Schiene.', 'gemischt', null, 'bund', null, true, null),
  (6936, 12, 'Radwegenetz ausbauen und dauerhaft finanzieren', 'Getrennte, durchgehende Radwege senken das Unfallrisiko nach vielen Studien; an Kreuzungen, wo die meisten schweren Unfälle passieren, hängt es von der Gestaltung ab. Bauen müssen Länder und Kommunen, der Bund kann fördern.', 'gemischt', null, 'bund', null, true, null),
  (6937, 12, 'Tempo 30 innerorts erleichtern oder zur Regel machen', 'Niedrigere Geschwindigkeit verringert Zahl und Schwere von Unfällen mit Radfahrenden und Fußgängern deutlich; auf Landstraßen und an Hauptverkehrsachsen, wo viele schwere Radunfälle passieren, ändert es nichts.', 'belegt', null, 'bund', null, true, null),
  (6966, 13, 'Genehmigungen beschleunigen, Netzausbau im überragenden öffentlichen Interesse, alternative Verlegemethoden', 'Verkürzt Genehmigungen für Masten und Leitungen und senkt Tiefbaukosten; wo sich der Ausbau wirtschaftlich nicht lohnt oder das Gelände schwierig ist, ändert das allein wenig.', 'gemischt', null, 'bund', null, true, null),
  (6967, 13, 'Staatliche Förderung gezielt dort, wo sich der private Ausbau nicht lohnt', 'Schließt Lücken, die der Markt nicht schließt; laut WIK ist die heutige Förderung aber teuer, anfällig für Überförderung und verdrängt teils privaten Ausbau – es kommt auf die Ausgestaltung an.', 'gemischt', 'https://www.wik.org/fileadmin/user_upload/Unternehmen/Veroeffentlichungen/Kurzstudien/2026/WIK_Kurzstudie_Anreizwirkung_der_derzeitigen_Gigabitfoerderung_auf_den_eigenwirtschaftlichen_Glasfaserausbau_in_Deutschland.pdf', 'bund', null, true, null),
  (6968, 13, 'Recht auf schnelles Internet: Mindestbandbreite erhöhen', 'Ein höherer Anspruch verpflichtet die Anbieter, auch unversorgte Haushalte anzuschließen; bei deutlich höheren Bandbreiten wird das teuer und langwierig, die Kosten tragen Anbieter oder Staat.', 'gemischt', null, 'bund', null, true, null),
  (6969, 13, 'Breitband- und Netzausbau auf dem Land voranbringen (ohne nähere Angaben)', 'Nennt das Ziel, aber keinen Weg, wie die Lücken geschlossen werden sollen.', 'offen', null, 'bund', null, true, null),
  (6983, 14, 'Zentrales Portal oder App mit digitaler Identität für alle Verwaltungsleistungen', 'Ein Zugang für alle Leistungen macht Angebote leichter auffindbar, was Nutzer laut eGovernment MONITOR vermissen; schneller wird es nur, wenn die Anträge dahinter auch digital bearbeitet werden. Braucht die Mitarbeit von Ländern und Kommunen, das Onlinezugangsgesetz zeigt, wie lange das dauert.', 'gemischt', 'https://initiatived21.de/publikationen/egovernment-monitor/2025', 'bund', null, true, null),
  (6984, 14, 'Once-Only: Register vernetzen, Daten nur einmal angeben', 'Setzt direkt daran an, dass Nachweise immer wieder eingereicht werden müssen; Länder wie Österreich und Estland zeigen, dass es funktioniert. Die Registermodernisierung ist aber ein Vorhaben über viele Jahre, und die Länder können nicht zur Anbindung verpflichtet werden.', 'belegt', 'https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Downloads/DE/Jahresberichte/2025-jahresbericht.pdf?__blob=publicationFile&v=5', 'bund', null, true, null),
  (6985, 14, 'Zuständigkeit für Verwaltungsdigitalisierung in einem Digitalministerium bündeln', 'Klare Zuständigkeit kann Projekte beschleunigen; seit 2025 gibt es ein solches Ministerium. Für Bürgerinnen und Bürger ändert sich erst etwas, wenn Leistungen tatsächlich digital und schneller werden.', 'offen', null, 'bund', null, true, null),
  (6986, 14, 'Automatisierung, KI und antragslose Verfahren in der Verwaltung', 'Kann den Personalmangel abfedern und Bearbeitungszeiten senken, wie der Normenkontrollrat empfiehlt; Voraussetzung sind digitale Akten und vernetzte Daten, die vielerorts fehlen.', 'gemischt', null, 'bund', null, true, null),
  (6987, 14, 'Öffentlichen Dienst als Arbeitgeber attraktiver machen', 'Setzt am Personalmangel an; der Bund regelt aber nur die Bedingungen seiner eigenen Beschäftigten, die meisten Stellen mit Bürgerkontakt liegen bei Ländern und Kommunen.', 'gemischt', null, 'bund', null, true, null),
  (6988, 14, 'Mehr Ermessen für Behörden, Regeln auf den Regelfall ausrichten', 'Kann Entscheidungen beschleunigen und Einzelfallprüfungen vermeiden; wie stark Vorschriften dadurch tatsächlich schlanker werden, ist offen.', 'offen', null, 'bund', null, true, null),
  (7011, 15, 'CO₂-Preis auf Kraftstoffe abschaffen', 'Senkt den Spritpreis 2026 um rund 15 bis 18 Cent je Liter; ab 2028 gilt aber der europäische Emissionshandel für Verkehr, den Deutschland nicht allein abschaffen kann. Die Einnahmen fehlen für Entlastungen an anderer Stelle.', 'belegt', null, 'bund', null, true, null),
  (7012, 15, 'CO₂-Einnahmen als Klimageld oder Klimabonus zurückzahlen', 'Gleicht die Mehrkosten durch den CO₂-Preis für viele Haushalte aus, senkt den Spritpreis aber nicht; wer viel fahren muss, wird nur teilweise entlastet. Ein Auszahlungsweg an alle Haushalte muss erst aufgebaut werden.', 'gemischt', null, 'bund', null, true, null),
  (7013, 15, 'Pendlerpauschale erhöhen', 'Entlastet Pendelnde über die Steuer; wer wenig verdient und kaum Steuern zahlt, hat wenig davon.', 'gemischt', null, 'bund', null, true, null),
  (7014, 15, 'Kaufförderung für Elektroautos für kleine und mittlere Einkommen (Prämie, Steuerabzug, Leasing)', 'Setzt direkt am Preis an, den Haushalte als größtes Hindernis nennen; soziales Leasing hat in Frankreich viele Haushalte mit kleinem Einkommen erreicht. Frühere Prämien in Deutschland wurden zum Teil mitgenommen und kamen vor allem besser Verdienenden zugute.', 'gemischt', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf', 'bund', null, true, null),
  (7015, 15, 'Öffentliche Ladeinfrastruktur ausbauen und Ladepreise senken', 'Hilft, wer nicht zu Hause laden kann, vor allem in Mehrparteienhäusern; öffentliches Laden bleibt aber meist teurer und aufwendiger als eine eigene Wallbox.', 'gemischt', null, 'bund', null, true, null),
  (7034, 16, 'Zuschüsse für neue klimafreundliche Heizungen fortführen oder ausbauen', 'Senkt die Investition, die viele Haushalte scheuen oder nicht aufbringen können, und setzt damit an den laut KfW größten Hindernissen an. Ob sie Haushalte mit wenig Geld erreicht, hängt von der Staffelung ab.', 'gemischt', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf', 'bund', null, true, null),
  (7035, 16, 'Wärmepumpen-Leasing oder Wärme-Contracting ohne hohe Startinvestition', 'Nimmt Haushalten die hohe Anfangsinvestition ab, die laut KfW oft fehlt; solche Angebote gibt es bisher nur vereinzelt, ihre Wirkung in der Breite ist kaum untersucht.', 'offen', null, 'bund', null, true, null),
  (7036, 16, 'Heizungsgesetz abschaffen, freie Wahl der Heizung', 'Schafft Wahlfreiheit und beendet den Streit um die 65-Prozent-Vorgabe; ist aber selbst eine weitere Änderung der Regeln, und mit dem steigenden CO₂-Preis bleibt offen, welche Heizung sich langfristig lohnt. 2026 mit dem Gebäudemodernisierungsgesetz weitgehend umgesetzt.', 'gemischt', null, 'bund', null, true, null),
  (7037, 16, 'Geltende Vorgaben beibehalten, Planungssicherheit bis 2045', 'Vermeidet weitere Wechsel der Regeln; die Vorgaben selbst waren stark umstritten, und ob sie Regierungswechsel überdauern, ist offen – 2026 wurden sie grundlegend geändert.', 'gemischt', null, 'bund', null, true, null),
  (7038, 16, 'Kommunale Wärmeplanung und Wärmenetze fördern', 'Beschleunigt die Wärmepläne, auf die viele Eigentümer warten, und den Bau von Wärmenetzen; planen und bauen müssen die Kommunen, der Bund kann nur Geld und Beratung geben.', 'gemischt', 'https://www.bbsr.bund.de/BBSR/DE/veroeffentlichungen/analysen-kompakt/2026/ak-09-2026.html', 'bund', null, true, null),
  (7039, 16, 'Modernisierungsumlage für energetische Sanierung abschaffen, Warmmietenneutralität', 'Schützt Mieterinnen und Mieter vor Mietsteigerungen durch den Heizungstausch; zugleich sinkt der Anreiz für Vermieter, die Heizung zu erneuern, sodass Mieter länger die Kosten alter Heizungen tragen können.', 'gemischt', null, 'bund', null, true, null),
  (7060, 12, 'Landes- und kommunale Straßen und Brücken sanieren (Landesprogramm)', 'Mehr Geld und klare Prioritäten für den Erhalt bauen den Sanierungsstau ab; seit 2025 stehen den Ländern Mittel aus dem Sondervermögen Infrastruktur zur Verfügung. Ob sie verbaut werden, hängt von Personal und Verfahren ab.', 'gemischt', null, 'land', null, true, null),
  (7061, 12, 'Kommunen finanziell stärken: Finanzausgleich, Investitionspauschalen, Altschulden (Landesprogramm)', 'Gibt Kommunen Spielraum für Investitionen; ob das Geld in Straßen fließt, entscheiden sie selbst, und der Landeshaushalt ist begrenzt.', 'gemischt', null, 'land', null, true, null),
  (7062, 12, 'Planung, Genehmigung und Vergabe im Land beschleunigen (Landesprogramm)', 'Das Land kann Bauordnung, Vergaberecht und Verwaltungsabläufe selbst ändern und so Verfahren verkürzen; laut KfW bremst aber vor allem fehlendes Personal.', 'gemischt', null, 'land', null, true, null),
  (7063, 12, 'Bauverwaltungen personell und finanziell stärken (Landesprogramm)', 'Setzt am größten Hemmnis an, das die KfW nennt; Ingenieurinnen und Ingenieure sind knapp, neue Stellen lassen sich nicht sofort besetzen.', 'gemischt', null, 'land', null, true, null),
  (7064, 12, 'Radwege ausbauen und sanieren, sichere und durchgängige Netze (Landesprogramm)', 'Getrennte, durchgehende Radwege und sichere Kreuzungen senken das Unfallrisiko nach vielen Studien; die Wirkung hängt von der Gestaltung ab, und neue Wege entstehen nur nach und nach.', 'gemischt', null, 'land', null, true, null),
  (7065, 12, 'Tempo 30 innerorts ausweiten, besonders an Schulen, Kitas und Seniorenheimen (Landesprogramm)', 'Niedrigere Geschwindigkeit verringert Zahl und Schwere von Unfällen mit Radfahrenden und Fußgängern; seit 2024 können Länder und Kommunen Tempo 30 leichter anordnen.', 'belegt', null, 'land', null, true, null),
  (7066, 12, 'Verkehrserziehung und Sicherheitsangebote, auch für Ältere (Landesprogramm)', 'Richtet sich an Gruppen mit hohem Risiko, etwa ältere Menschen auf Pedelecs; wie stark Trainings die Zahl schwerer Unfälle senken, ist kaum untersucht.', 'offen', null, 'land', null, true, null),
  (7125, 14, 'Verwaltungsleistungen im Land durchgängig digital, zentrales Portal oder App (Landesprogramm)', 'Setzt an den Hürden an, die Nutzer nennen: schwere Auffindbarkeit und Anträge, die hinterher doch auf Papier bearbeitet werden. Die meisten Leistungen erbringen Land und Kommunen selbst.', 'gemischt', null, 'land', null, true, null),
  (7126, 14, 'Verwaltungsmodernisierung zentral im Land bündeln (Landesprogramm)', 'Klare Zuständigkeit kann Digitalisierungsprojekte beschleunigen; für Bürgerinnen und Bürger ändert sich erst etwas, wenn Leistungen tatsächlich einfacher werden.', 'offen', null, 'land', null, true, null),
  (7127, 14, 'KI und Automatisierung zur Entlastung der Verwaltung (Landesprogramm)', 'Kann Personalmangel abfedern und Bearbeitungszeiten senken; Voraussetzung sind digitale Akten und Daten, die vielerorts fehlen.', 'gemischt', null, 'land', null, true, null),
  (7128, 14, 'Öffentlichen Dienst im Land attraktiver machen: Ausbildung, Bezahlung, Arbeitsbedingungen (Landesprogramm)', 'Setzt am Personalmangel an, den der Normenkontrollrat als drängend beschreibt; das Land konkurriert aber mit Wirtschaft und anderen Ländern um dieselben Fachkräfte.', 'gemischt', null, 'land', null, true, null),
  (7129, 14, 'Terminvergabe in Bürgerämtern verbessern (Landesprogramm)', 'Verteilt vorhandene Termine besser und verkürzt Wartezeiten etwas; mehr Kapazität entsteht dadurch nicht.', 'offen', null, 'land', null, true, null),
  (7158, 16, 'Kommunale Wärmeplanung und Wärmenetze unterstützen: Beratung, Personal, Förderung (Landesprogramm)', 'Beschleunigt die Wärmepläne und den Bau von Wärmenetzen, auf die viele Eigentümer warten; das Land kann Kommunen mit Geld und Fachleuten helfen.', 'gemischt', null, 'land', null, true, null),
  (7159, 16, 'Kommunale Wärmeplanung vereinfachen, realistische Vorgaben (Landesprogramm)', 'Kann die Planung für kleine Gemeinden beschleunigen; wenn Pläne gröber werden, wissen Eigentümer aber weniger genau, was kommt.', 'offen', null, 'land', null, true, null),
  (7160, 16, 'Pflicht zur kommunalen Wärmeplanung abschaffen (Landesprogramm)', 'Nimmt Kommunen eine Pflicht ab und Eigentümern das Warten auf einen Plan, schafft aber keine Klarheit, ob ein Wärmenetz kommt. Die Pflicht steht im Bundesrecht; das Land kann nur sein Ausführungsgesetz ändern oder im Bundesrat werben.', 'offen', null, 'land', null, true, null),
  (7228, 11, 'Geringqualifizierte zum Berufsabschluss führen (Bund)', 'Ein Berufsabschluss führt oft aus dem Niedriglohnbereich heraus, weil Fachkräfte deutlich mehr verdienen als Helfer; die Wirkung stellt sich erst über Jahre ein, und die Programme nennen kaum konkrete Instrumente.', 'gemischt', null, 'bund', null, true, null),
  (7232, 2, 'Kurzzeitvermietung und Zweckentfremdung begrenzen (Bund)', 'Weniger Ferienwohnungen und Leerstand bringen Wohnungen zurück auf den Mietmarkt, vor allem in Großstädten; bundesweit ist der Anteil klein. Zweckentfremdungsverbote erlassen die Länder, der Bund kann den Rahmen setzen.', 'gemischt', null, 'bund', null, true, null),
  (7258, 15, 'Elektro- und verbrauchsarme Fahrzeuge fördern, um weniger Kraftstoff zu brauchen (Bund, Ölabhängigkeit)', 'Jedes ersetzte Verbrennerfahrzeug braucht kein Benzin oder Diesel mehr. Bei 4,1 % Elektroanteil im Pkw-Bestand (1. 1. 2026) und langer Erneuerungszeit wirkt das erst über Jahre und schützt nicht vor einem Preisschock im laufenden Jahr.', 'gemischt', 'https://www.kba.de/DE/Presse/Pressemitteilungen/Fahrzeugbestand/2026/pm09_fz_bestand_pm_komplett.html', 'bund', null, true, null),
  (7259, 15, 'Alternative Kraftstoffe wie E-Fuels zulassen und gleichstellen (Bund, Ölabhängigkeit)', 'Strombasierte Kraftstoffe entkoppeln den Preis vom Rohöl, sind aber nicht kommerziell verfügbar und würden zunächst etwa 2 Euro je Liter kosten (Benzin im Großhandel 0,50). Bis 2035 deckt es höchstens die Hälfte des Bedarfs von Luft-, Schifffahrt und Chemie. Das Verbrennerverbot ist EU-Recht.', 'offen', 'https://www.pik-potsdam.de/members/Ueckerdt/E-Fuels_Stand-und-Projektionen_PIK-Potsdam.pdf', 'bund', null, true, null),
  (7260, 15, 'Energie- und Umsatzsteuer in Preiskrisen schnell senken (Bund)', 'Senkt den Preis sofort, aber nur befristet; der Tankrabatt 2026 kam laut Monopolkommission zu einem großen Teil, aber nicht vollständig an. Die schnelle Senkung der Umsatzsteuer braucht EU-Zustimmung. Das Programm nennt Güter des täglichen Bedarfs, nicht nur Kraftstoff.', 'gemischt', 'https://www.monopolkommission.de/fileadmin/monopolkommission/Indexierte_Dateien/PDFs/Policy_Briefs/Monopolkommission-Policy-Brief-16-2026-Tankrabatt.pdf#page=1', 'bund', null, true, null),
  (7272, 17, 'Bedarfsgerechte Betreuungsplätze und Rechtsanspruch verlässlich sichern (Land)', 'Ein erfüllter Anspruch verbessert den Zugang direkt, setzt aber ausreichende Plätze und Personal voraus. Die Umsetzung hängt deshalb von regionaler Kapazität und Finanzierung ab.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'land', null, true, 'blind'),
  (7273, 17, 'Genehmigungsverfahren für Kita-Ausbau beschleunigen (Land)', 'Kürzere Verfahren können den Ausbau erleichtern, schaffen aber weder Bauflächen noch Personal. Verwaltungsvereinfachungen sind innerhalb einer Wahlperiode realistisch.', 'offen', null, 'land', null, true, 'blind'),
  (7274, 17, 'Kita-Plätze bedarfsgerecht ausbauen, erhalten und sanieren (Land)', 'Zusätzliche und gesicherte Plätze wirken unmittelbar gegen Angebotslücken; der tatsächliche Effekt hängt von Personalverfügbarkeit und regionaler Planung ab. Investitionen und laufende Kosten begrenzen das Tempo.', 'belegt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'land', null, true, 'blind'),
  (7275, 17, 'Kita-Träger und Kindertagespflege bedarfsgerecht finanzieren (Land)', 'Eine verlässliche Finanzierung kann Plätze erhalten und Ausbau ermöglichen. Der Effekt hängt davon ab, ob Mittel zusätzlich bereitgestellt und tatsächlich für Kapazitäten eingesetzt werden.', 'gemischt', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'land', null, true, 'blind'),
  (7276, 17, 'Kommunale Bedarfsplanung und flexible Angebotssteuerung stärken (Land)', 'Kleinräumige Planung kann Plätze besser an Bedarf und Bevölkerungsentwicklung anpassen. Sie behebt einen landesweiten Personal- oder Finanzmangel nicht allein.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'land', null, true, 'blind'),
  (7277, 17, 'Flexible und ergänzende Betreuungsangebote ausbauen (Land)', 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'gemischt', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'land', null, true, 'blind'),
  (7278, 17, 'Kita-Betreuung rund um die Uhr anbieten (Land)', 'Nachtbetreuung hilft nur Familien mit entsprechendem Bedarf und löst die allgemeine Angebotslücke kaum. Der hohe Personal- und Organisationsaufwand erschwert eine Umsetzung in der Wahlperiode.', 'offen', null, 'land', null, true, 'blind'),
  (7279, 17, 'Betriebliche Kinderbetreuung fördern (Land)', 'Betriebskitas schaffen zusätzliche Plätze und können Arbeitszeiten besser abdecken. Sie erreichen nicht alle Familien und benötigen Personal sowie tragfähige Trägerfinanzierung.', 'offen', null, 'land', null, true, 'blind'),
  (7280, 17, 'Kommunen beim Ausbau wohnortnaher Betreuungsplätze unterstützen (Bund)', 'Investitionshilfen können zusätzliche Plätze und erreichbare Angebote ermöglichen. Die Wirkung hängt von kommunaler Planung, Kofinanzierung und verfügbarem Personal ab.', 'belegt', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'bund', null, true, 'blind'),
  (7281, 17, 'Betriebliche Kinderbetreuung fördern und steuerlich unterstützen (Bund)', 'Anreize können zusätzliche betriebliche Plätze mobilisieren, besonders für Beschäftigte mit passenden Arbeitszeiten. Wie viele zusätzliche Plätze dadurch entstehen, ist für die konkrete Ausgestaltung unsicher.', 'offen', null, 'bund', null, true, 'blind'),
  (7282, 17, 'Kitagutschein automatisch versenden und Zugangshilfen bündeln (Land)', 'Eine automatische Information und Vermittlung kann administrative Hürden senken. Sie erhöht das Platzangebot nicht und hilft nur, wenn passende Plätze verfügbar sind.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'land', null, true, 'blind'),
  (7283, 17, 'Kita-Platzvergabe transparent und digital organisieren (Land)', 'Transparente Verfahren können Mehrfachanmeldungen und ungerechte Zugänge reduzieren. Ein digitales System schafft selbst keine zusätzlichen Betreuungsplätze.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'land', null, true, 'blind'),
  (7284, 17, 'Belegte Kita-Plätze für kurzfristigen Bedarf vorhalten (Land)', 'Reservierte Plätze können einzelne Zugangsprobleme abfedern, verringern aber die Zahl regulär verfügbarer Plätze. Der Nutzen hängt von lokaler Nachfrage und verlässlicher Finanzierung ab.', 'offen', null, 'land', null, true, 'blind'),
  (7285, 17, 'Über Kita-Leistungen innerhalb fester Frist entscheiden (Land)', 'Schnellere Bescheide erleichtern die Planung und beseitigen Verzögerungen im Verwaltungszugang. Sie schaffen keinen Platz, wenn das Angebot fehlt.', 'offen', null, 'land', null, true, 'blind'),
  (7286, 17, 'Personalschlüssel auf 1:3 in Krippen und 1:7,5 in Kindergärten verbessern (Land)', 'Die konkreten Zielwerte setzen direkt an der Personalausstattung an, die pädagogische Interaktionen ermöglicht. Die Verbesserung ist wirksam, erfordert angesichts des Fachkräftemangels aber zusätzliche Personal- und Finanzressourcen.', 'belegt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'land', null, true, 'blind'),
  (7287, 17, 'Tatsächliche Personal-Kind-Relation schrittweise verbessern (Land)', 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'belegt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'land', null, true, 'blind'),
  (7288, 17, 'Personalschlüssel in Krippen auf 1:4 und in Kindergärten auf 1:10 verbessern (Land)', 'Die Zielwerte verbessern die Personalausstattung gegenüber ungünstigen Ausgangslagen, bleiben aber hinter den fachlichen Empfehlungen zurück. Zusätzliches Personal ist nötig.', 'belegt', 'https://www.dji.de/themen/kinderbetreuung/plaetze-und-personalschluessel.html', 'land', null, true, 'blind'),
  (7289, 17, 'Personalschlüssel in Krippen auf 1:5 und in Kindergärten auf 1:13 verbessern (Land)', 'Die festen Stufen verbessern die Personalausstattung, bleiben aber deutlich hinter den fachlichen Empfehlungen von 1:3 und 1:7,5 zurück. Der Zeitplan ist bestimmt, das zusätzliche Personal muss bei Fachkräftemangel aber erst gewonnen werden.', 'belegt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'land', null, true, 'nicht_blind'),
  (7290, 17, 'Bundesweite Personal-Kind-Relation einschließlich Ausfallzeiten festlegen (Bund)', 'Einheitliche Mindeststandards können die Qualität und Berücksichtigung von Ausfällen stärken. Die Länder setzen sie um; Personalverfügbarkeit und Finanzierung bestimmen die tatsächliche Wirkung.', 'belegt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'bund', null, true, 'blind'),
  (7291, 17, 'Vergütung und Arbeitsbedingungen in Kitas verbessern (Land)', 'Bessere Bezahlung und Arbeitsbedingungen können die Attraktivität und Bindung von Fachkräften erhöhen. Der Fachkräftemangel und die Tarif- und Haushaltskosten begrenzen Geschwindigkeit und Reichweite.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'land', null, true, 'blind'),
  (7292, 17, 'Tarifvergütung in Sozial- und Erziehungsdiensten refinanzieren (Bund)', 'Die Refinanzierung kann Trägern ermöglichen, tarifliche Löhne zu zahlen und Personal zu halten. Der Bund kann Kosten mittragen, aber die tatsächliche Personalgewinnung ist nicht garantiert.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'bund', null, true, 'blind'),
  (7293, 17, 'Ausbildungskapazitäten erweitern und Qualifizierung erleichtern (Land)', 'Mehr Ausbildungsplätze, Praxisanteile und Quereinstiege können mittelfristig den Personalzugang verbessern. Fehlende Lehrkräfte, Räume und Ausbildungserfolg begrenzen den Zuwachs.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'land', null, true, 'blind'),
  (7294, 17, 'Erzieherausbildung und Praxisphasen vergüten (Land)', 'Vergütung kann den Zugang zur Ausbildung erleichtern und die Zahl der Auszubildenden erhöhen. Ein unmittelbarer Effekt auf verfügbare Fachkräfte entsteht erst nach Ausbildungsabschluss.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'land', null, true, 'blind'),
  (7295, 17, 'Ausbildung und Fachkräftegewinnung für Kitas fördern (Bund)', 'Bundesmittel für vergütete Ausbildung, Kapazitäten und Qualifizierung können den Ländern beim Aufbau des Personals helfen. Wirkung und Zeitbedarf hängen von Länderumsetzung und Ausbildungserfolg ab.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'bund', null, true, 'blind'),
  (7296, 17, 'Verwaltungs- und Dokumentationsaufwand in Kitas reduzieren (Land)', 'Weniger unnötige Dokumentation kann Fachkräfte und Leitung entlasten. Freigesetzte Zeit ersetzt keine zusätzlichen Betreuungskräfte und hängt von einer sorgfältigen Auswahl der Pflichten ab.', 'offen', null, 'land', null, true, 'blind'),
  (7297, 17, 'Pädagogische Teams durch Verwaltungs- und Hauswirtschaftskräfte entlasten (Land)', 'Zusätzliche Unterstützung kann pädagogischen Fachkräften mehr Zeit für Kinder geben. Sie benötigt weiteres Personal und verbessert nicht automatisch die Fachkraft-Kind-Relation.', 'offen', null, 'land', null, true, 'blind'),
  (7298, 17, 'Multiprofessionelle Teams und zusätzliche Förderung stärken (Land)', 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'land', null, true, 'blind'),
  (7299, 17, 'Kindertagespflege fair vergüten und verlässlich unterstützen (Land)', 'Faire Entgelte, Beratung und klare Vereinbarungen können Tagespflegepersonen halten und zusätzliche Plätze ermöglichen. Die Zahl der erreichbaren Plätze bleibt von der Gewinnung und Bindung der Betreuungspersonen abhängig.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'land', null, true, 'blind'),
  (7300, 17, 'Kita-Personalstandards auf Kindertagespflege übertragen (Land)', 'Eine bessere Personalausstattung kann die Betreuungsqualität erhöhen. Eine Übertragung ohne Einkommensverluste erfordert zusätzliche Finanzierung und muss zur Struktur der Tagespflege passen.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'land', null, true, 'blind'),
  (7301, 17, 'Kindertagespflege bundesweit als Betreuungsangebot stärken (Bund)', 'Bundesunterstützung kann die Länder beim Erhalt und Ausbau ergänzender Betreuungsplätze unterstützen. Die konkrete Wirkung hängt von Umsetzung und dauerhafter Finanzierung vor Ort ab.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'bund', null, true, 'blind'),
  (7302, 17, 'Kita-Beiträge landesweit abschaffen und Kosten dauerhaft finanzieren (Land)', 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'gemischt', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'land', null, true, 'blind'),
  (7303, 17, 'Kita-Beiträge bundesweit abschaffen oder senken (Bund)', 'Geringere Beiträge entlasten Familien und können den Zugang erleichtern, beseitigen aber nicht alle Zusatzkosten. Mehr Nachfrage kann bei knappen Plätzen den Zugang erschweren, wenn der Ausbau nicht Schritt hält.', 'gemischt', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'bund', null, true, 'blind'),
  (7304, 17, 'Beitragsermäßigungen für Mehrkinderfamilien sichern (Land)', 'Ermäßigungen mindern die finanzielle Belastung größerer Familien, ohne die Kosten für alle Eltern abzuschaffen. Die Entlastung erreicht nur Familien, die die jeweilige Regelung nutzen.', 'gemischt', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'land', null, true, 'blind'),
  (7305, 17, 'Einkommensabhängige Kita-Beiträge bundesweit als Standard vorgeben (Bund)', 'Einkommensabhängige Beiträge können die Belastung gezielter bei Familien mit geringem Einkommen senken. Der Bund kann Vorgaben zur Staffelung machen, Höhe und Erhebung der Beiträge liegen aber bei Ländern und Kommunen; die Angebotsknappheit bleibt.', 'gemischt', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'bund', null, true, 'nicht_blind'),
  (7306, 17, 'Kinderbetreuungskosten steuerlich absetzen (Bund)', 'Steuerliche Abzüge können einen Teil der Kosten kompensieren. Die Entlastung ist geringer oder fehlt bei Familien mit niedriger Steuerlast und löst weder Platzmangel noch hohe laufende Beiträge direkt.', 'gemischt', 'https://www.oecd.org/en/publications/education-at-a-glance-2024_c00cad36-en.html', 'bund', null, true, 'blind'),
  (7307, 17, 'Personal- und Elternkosten der Kita-Qualität bedarfsgerecht finanzieren (Land)', 'Eine Finanzierung der tatsächlichen Kosten kann bessere Personalausstattung ermöglichen und Beitragsbelastungen begrenzen. Die Ausgabenhöhe und die Verteilung zwischen Land, Kommunen und Trägern sind anspruchsvoll.', 'gemischt', 'https://www.dji.de/themen/kinderbetreuung/plaetze-und-personalschluessel.html', 'land', null, true, 'blind'),
  (7308, 17, 'Kinderbetreuungskosten über ein Lebenschancen-BAföG mitfinanzieren (Bund)', 'Ein zweckgebundener Zuschuss kann einzelne Familien bei den Kosten entlasten. Seine Reichweite hängt von Anspruchshöhe und Zugang ab und beeinflusst das Platzangebot nicht.', 'offen', null, 'bund', null, true, 'blind'),
  (7309, 17, 'Landeserziehungsgeld für Kinder unter drei Jahren einführen (Land)', 'Ein Geldbetrag kann Familien finanziell entlasten, sichert aber keinen Kita-Platz und kann die Nachfrage nach Betreuung sogar senken. Die Kosten hängen von Anspruch und Leistungshöhe ab.', 'gemischt', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'land', null, true, 'blind'),
  (7310, 17, 'Mittagsverpflegung in Kitas kostenfrei anbieten (Land)', 'Kostenfreie Mahlzeiten senken einen Teil der Familienausgaben, lassen Elternbeiträge und weitere Zusatzkosten aber bestehen. Die Wirkung auf die Gesamtbelastung ist daher begrenzt.', 'offen', null, 'land', null, true, 'blind'),
  (7311, 17, 'Verpflichtende Zusatzbeiträge von Eltern verhindern (Land)', 'Das Verhindern verpflichtender Zusatzforderungen kann unerwartete Kosten begrenzen. Es senkt nicht automatisch die regulären Elternbeiträge und muss mit der Finanzierung zusätzlicher Leistungen vereinbar sein.', 'offen', null, 'land', null, true, 'blind'),
  (7312, 17, 'Mindestankündigungsfristen und Schlichtung bei Kita-Streiks einführen (Bund)', 'Vorankündigung und Schlichtung könnten Familien mehr Planungssicherheit geben. Sie verhindern weder krankheitsbedingte Ausfälle noch lösen sie Personalengpässe; arbeitsrechtliche Ausgestaltung ist anspruchsvoll.', 'offen', null, 'bund', null, true, 'blind'),
  (7313, 17, 'Zusätzliche Mittel zur kurzfristigen Personalsicherung bereitstellen (Land)', 'Zusätzliche Personalressourcen können Ausfälle auffangen und Betreuung stabilisieren. Eine dauerhafte Wirkung setzt verlässliche Finanzierung und verfügbare Fachkräfte voraus.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'land', null, true, 'blind'),
  (7314, 17, 'Kita-Qualitätsmittel für Personal und Leitungszeit einsetzen (Land)', 'Zusätzliche pädagogische Leitungs- und Personalzeit kann die Arbeit in Einrichtungen verbessern. Die Wirkung hängt davon ab, dass Mittel zusätzlich und dauerhaft für qualifiziertes Personal eingesetzt werden.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'land', null, true, 'blind'),
  (7315, 17, 'Betreuungsgehalt zur Entlastung und Senkung der Platznachfrage einführen (Bund)', 'Ein Betreuungsgehalt kann einzelne Familien finanziell entlasten, stellt aber keine bedarfsgerechte externe Betreuung sicher. Ob es die Platznachfrage dauerhaft senkt, ist unklar.', 'offen', null, 'bund', null, true, 'blind'),
  (7316, 17, 'Gesundheits-, Lärm- und Hitzeschutz für Kita-Beschäftigte verbessern (Land)', 'Bessere Arbeitsbedingungen können Belastungen mindern und die Bindung von Personal unterstützen. Der direkte Beitrag zu mehr verfügbaren Betreuungsstunden ist begrenzt und nicht gut untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (7317, 17, 'Kita-Platzvergabe bundesweit nach Bedarf priorisieren (Bund)', 'Eine Priorisierung kann Plätze für bestimmte Familien zugänglicher machen, erhöht aber nicht die Zahl der Plätze und kann andere Familien benachteiligen. Ein bundesweiter Eingriff in die Vergabe erfordert Abstimmung mit Ländern und Kommunen.', 'offen', null, 'bund', null, true, 'blind'),
  (7318, 17, 'Verpflichtenden beitragsfreien Kita-Besuch bei Deutschförderbedarf einführen (Bund)', 'Frühe Sprachförderung kann den Förderzugang verbessern, aber eine Pflicht erhöht nicht das knappe Platzangebot. Bedarfsermittlung, Zuständigkeit und Durchsetzung sind anspruchsvoll.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'bund', null, true, 'blind'),
  (7319, 17, 'Rechtsanspruch auf zehn Stunden Kita-Betreuung täglich schaffen (Land)', 'Ein längerer Anspruch kann den Betreuungsumfang für Familien mit entsprechendem Bedarf direkt verbessern. Er verlangt zusätzliche Plätze und Personal und ist ohne entsprechende Kapazitäten innerhalb einer Wahlperiode schwer erfüllbar.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'land', null, true, 'blind'),
  (7320, 17, 'Bundeseinheitliche Qualitätsstandards für Kitas festlegen (Bund)', 'Gemeinsame Standards können regionale Mindestqualität und Ausfallberücksichtigung verbessern. Ihre Umsetzung erfordert Abstimmung mit den Ländern und zusätzliche Mittel, wenn sie über bestehende Ausstattung hinausgehen.', 'gemischt', 'https://www.dji.de/themen/kinderbetreuung/plaetze-und-personalschluessel.html', 'bund', null, true, 'blind'),
  (7321, 17, 'Zusatzmittel für Kitas mit Platzmangel oder sozialem Förderbedarf bereitstellen (Bund)', 'Gezielte Mittel können zusätzliche Kapazitäten und Förderung an Orten mit hohem Bedarf unterstützen. Ob Plätze entstehen, hängt von Umsetzung, Personal und ergänzender kommunaler Finanzierung ab.', 'gemischt', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'bund', null, true, 'blind'),
  (7322, 17, 'Betreuungsanspruch bis zum 14. Lebensjahr aufrechterhalten (Land)', 'Ein Anspruch für ältere Kinder geht über das für dieses Thema erforderliche Kita-Angebot hinaus und schafft keinen Platz. Umfang, Zuständigkeiten und Finanzierung machen die Umsetzung schwierig.', 'offen', null, 'land', null, true, 'blind'),
  (7323, 17, 'Zusätzliche pädagogische Kita-Leistungen gegen Elternbeiträge ermöglichen (Land)', 'Zusätzliche kostenpflichtige Leistungen verbessern die Bezahlbarkeit der Grundbetreuung nicht und können die Belastung von Familien erhöhen. Die Erlaubnis ist administrativ umsetzbar, wirkt aber dem Kostenziel nicht entgegen.', 'offen', null, 'land', null, true, 'blind'),
  (7324, 17, 'Kinderbetreuung für Hochschulangehörige schaffen (Land)', 'Ein gezieltes Angebot kann den Zugang für Hochschulangehörige verbessern, löst aber nur einen kleinen Teil des allgemeinen Platzmangels. Personal- und Investitionsbedarf bleiben bestehen.', 'offen', null, 'land', null, true, 'blind'),
  (7481, 9, 'Mehr Personal und Ausstattung für Staatsanwaltschaften und Gerichte, gemeinsam mit den Ländern (Bund)', 'Fehlende Staatsanwälte und Richter gelten nach der Personalbedarfsberechnung als ein Hauptgrund für rund eine Million offene Verfahren. Mehr Personal setzt dort an. Der Bund kann über einen Pakt aber nur mitfinanzieren, und Nachwuchs ist knapp.', 'belegt', 'https://www.drb.de/newsroom/presse-mediencenter/nachrichten-auf-einen-blick/nachricht/news/staatsanwaltschaften-am-limit-1', 'bund', null, true, 'blind'),
  (7482, 9, 'Personal, Ausstattung und Befugnisse von Polizei und Ermittlungsbehörden stärken (Bund)', 'Mehr und besser ausgestattete Ermittler können mehr Taten aufklären, und Studien aus den USA finden weniger Kriminalität bei mehr Polizei. Der Bund steuert aber nur BKA und Bundespolizei. Ohne konkreten Umfang ist die Wirkung unbestimmt.', 'gemischt', null, 'bund', null, true, 'blind'),
  (7483, 9, 'Digitalisierung von Justiz und Gerichtsverfahren (Bund)', 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und IT-Projekte der Justiz brauchen viele Jahre und die Mitarbeit der Länder.', 'offen', null, 'bund', null, true, 'blind'),
  (7484, 9, 'KI-gestützte Datenanalyse und erweiterte digitale Ermittlungsbefugnisse (Bund)', 'Automatisierte Analysen und Online-Befugnisse können Ermittlungen beschleunigen. Unabhängige Belege für höhere Aufklärungsquoten fehlen, und das Bundesverfassungsgericht hat enge Grenzen gesetzt.', 'offen', null, 'bund', null, true, 'blind'),
  (7485, 9, 'Vorratsdatenspeicherung und weitere Überwachungsbefugnisse ablehnen oder zurücknehmen (Bund)', 'Das Ablehnen von Befugnissen schützt Grundrechte, bringt die Aufklärung aber nicht voran. Laut einer Studie des Max-Planck-Instituts brachte die Vorratsdatenspeicherung keine messbar höhere Aufklärung, der Verlust wäre also gering.', 'gemischt', 'https://heise.de/newsticker/meldung/Studie-Vorratsdatenspeicherung-verbessert-die-Aufklaerungsquote-nicht-1423035.html', 'bund', null, true, 'blind'),
  (7486, 9, 'Quick-Freeze-Verfahren zur Datensicherung im Verdachtsfall (Bund)', 'Quick Freeze ist grundrechtsschonend und schnell umsetzbar. Es greift aber nur bei Daten, die zum Zeitpunkt der Anordnung noch vorhanden sind. Bei IP-Adressen ist das oft nicht mehr der Fall, daher ist der Nutzen bei Onlinebetrug begrenzt.', 'gemischt', 'https://heise.de/newsticker/meldung/Studie-Vorratsdatenspeicherung-verbessert-die-Aufklaerungsquote-nicht-1423035.html', 'bund', null, true, 'blind'),
  (7487, 9, 'Login-Falle zur Identifizierung anonymer Täter im Netz (Bund)', 'Die Login-Falle kann anonyme Konten gezielt identifizieren und ist rechtlich wenig umstritten. Sie wirkt aber nur bei Konten, die erneut genutzt werden, und erfasst Betrug aus dem Ausland kaum. Zur Wirkung gibt es kaum Daten.', 'offen', null, 'bund', null, true, 'blind'),
  (7488, 9, 'Europol zu einem europäischen Kriminalamt ausbauen, grenznahe Polizeizusammenarbeit stärken (Bund)', 'Viele Online- und organisierte Taten kommen aus dem Ausland, deshalb setzt eine bessere Zusammenarbeit an einer Ursache an. Operative Befugnisse für Europol erfordern aber eine Änderung der EU-Verträge mit allen Mitgliedstaaten.', 'offen', null, 'bund', null, true, 'blind'),
  (7489, 9, 'Organisierte Kriminalität: Vermögensabschöpfung erleichtern, Beweislast umkehren, Geldwäsche bekämpfen (Bund)', 'Eine leichtere Einziehung von Vermögen trifft kriminelle Strukturen finanziell. Auf die Aufklärung alltäglicher Straftaten wirkt sie kaum. Eine volle Beweislastumkehr steht im Konflikt mit Unschuldsvermutung und Eigentumsschutz.', 'offen', null, 'bund', null, true, 'blind'),
  (7490, 9, 'Bagatelldelikte entkriminalisieren und Ersatzfreiheitsstrafen vermeiden, um die Justiz zu entlasten (Bund)', 'Allein Fahren ohne Fahrschein macht rund 6 % der Verurteilungen und über die Hälfte der Ersatzfreiheitsstrafen aus. Eine Streichung entlastet Justiz und Haft spürbar. Die Aufklärung schwerer Taten verbessert sie nur indirekt.', 'belegt', null, 'bund', null, true, 'blind'),
  (7491, 9, 'Strafen für einzelne Gewalt- und Sexualdelikte verschärfen (Bund)', 'Höhere Strafen sind rechtlich leicht umsetzbar und benennen das Unrecht klarer. Die Forschung zeigt aber übereinstimmend: Abschreckend wirkt vor allem das Risiko, erwischt zu werden, kaum die Höhe der Strafe.', 'belegt', 'https://prohic.nl/wp-content/uploads/2020/11/2020-06-02-DeterrenceMetaNagin.2013.pdf', 'bund', null, true, 'blind'),
  (7492, 9, 'Jugendstrafrecht verschärfen: Strafmündigkeit senken, Heranwachsende nach Erwachsenenstrafrecht (Bund)', 'Dafür spricht, dass Intensivtäter früher gestoppt werden können. Rückfallstudien zeigen aber keinen Vorteil härterer Sanktionen bei jungen Menschen, eher höhere Rückfallraten. Für Kinder fehlen zudem geeignete Einrichtungen.', 'belegt', 'https://www.uni-konstanz.de/rtf/kis/heinz-sanktionen-jugendstrafrecht-12-thesen.htm', 'bund', null, true, 'blind'),
  (7493, 9, 'Zustimmungslösung im Sexualstrafrecht („Nur Ja heißt Ja“) (Bund)', 'In Schweden stiegen die Verurteilungen nach der Reform deutlich. Deutschland erfasst seit 2016 aber schon Taten gegen den erkennbaren Willen, daher ist der Zusatznutzen kleiner. An der geringen Anzeigebereitschaft ändert die Reform wenig.', 'gemischt', 'https://www.thelocal.se/20200616/how-swedens-new-consent-law-led-to-a-75-rise-in-rape-convictions/', 'bund', null, true, 'blind'),
  (7494, 9, 'Frauenhäuser und Beratung ausbauen, Rechtsanspruch auf Schutz mit Bundesfinanzierung (Bund)', 'Es fehlen tausende Schutzplätze; Schutz und Beratung helfen Betroffenen direkt, aus der Gewalt herauszukommen. Die Gewalt selbst wird dadurch weniger verhindert. Der Bund beteiligt sich bereits, der Ausbau braucht aber Jahre und Personal.', 'belegt', 'https://www.institut-fuer-menschenrechte.de/aktuelles/detail/gewalt-gegen-frauen-beratungs-und-unterstuetzungsstrukturen-in-stadt-und-land-sichern', 'bund', null, true, 'blind'),
  (7495, 9, 'Elektronische Fußfessel und schärferes Gewaltschutzgesetz bei häuslicher Gewalt (Bund)', 'In Spanien wurde seit 2009 keine Frau getötet, deren Täter überwacht wurde. Die Maßnahme setzt bei Hochrisikofällen an. Sie erreicht aber nur wenige Fälle und setzt voraus, dass die Gewalt bereits angezeigt wurde.', 'belegt', 'https://www.france24.com/en/20200926-domestic-violence-electronic-bracelets-are-a-first-step-but-we-have-to-go-further', 'bund', null, true, 'blind'),
  (7496, 9, 'Täterarbeit und Prävention gegen Partnerschaftsgewalt ausbauen (Bund)', 'Eine Meta-Analyse findet bis zu zwei Jahre nach Täterprogrammen deutlich weniger Rückfälle, danach keinen gesicherten Effekt mehr. Die Angebote liegen überwiegend bei den Ländern, der Bund kann fördern.', 'gemischt', 'https://pure.qub.ac.uk/en/publications/the-effectiveness-of-interventions-to-prevent-recidivism-in-perpe/', 'bund', null, true, 'blind'),
  (7497, 9, 'Ausweisung und Abschiebung ausländischer Straftäter erleichtern und vorrangig betreiben (Bund)', 'Die Maßnahme verhindert weitere Taten der Abgeschobenen im Inland. Sie betrifft aber nur einen kleinen Teil der Tatverdächtigen und lässt die Ursachen laut Forschung unberührt. Ob sie gelingt, hängt von der Mitarbeit der Herkunftsstaaten ab.', 'offen', 'https://www.swp-berlin.org/10.18449/2021S12/', 'bund', null, true, 'blind'),
  (7498, 9, 'Nachrichtendienste und Gefährderüberwachung mit Personal und Befugnissen stärken (Bund)', 'Eine frühe Aufklärung von Netzwerken und Gefährdern kann schwere Anschläge verhindern. Unabhängige Wirkungsstudien fehlen, und neue Befugnisse stoßen auf verfassungsrechtliche Grenzen.', 'offen', null, 'bund', null, true, 'blind'),
  (7499, 9, 'Verfassungsschutz grundlegend umbauen oder durch andere Stelle ersetzen (Bund)', 'Bekannte Fehler wie im V-Leute-System sprechen für eine Reform. Ein Umbau kann aber zunächst die Früherkennung schwächen. Belege, dass eine andere Organisationsform extremistische Taten besser verhindert, fehlen.', 'offen', null, 'bund', null, true, 'blind'),
  (7500, 9, 'Vereins- und Organisationsverbote gegen extremistische Gruppen (Bund)', 'Verbote zerschlagen Strukturen, Vermögen und Treffpunkte, und das Innenministerium kann sie selbst aussprechen. Mitglieder organisieren sich aber oft neu. Zur Wirkung auf Straftaten gibt es kaum Studien.', 'offen', null, 'bund', null, true, 'blind'),
  (7501, 9, 'Extremisten konsequent entwaffnen (Bund)', 'Ohne legale Waffen sind schwere Gewalttaten von Extremisten schwerer möglich, und das Waffenrecht erlaubt den Entzug bereits. Illegal beschaffte Waffen erfasst die Maßnahme nicht, und Wirkungsstudien fehlen.', 'offen', null, 'bund', null, true, 'blind'),
  (7502, 9, 'Ausstiegs- und Präventionsangebote gegen Extremismus dauerhaft finanzieren (Bund)', 'Eine Auswertung eines Aussteigerprogramms fand bei 94 % der Betreuten keine neuen Straftaten, allerdings ohne Vergleichsgruppe. Belastbare Wirkungsstudien sind selten. Ob der Bund für ein Fördergesetz zuständig ist, ist umstritten.', 'gemischt', 'https://www.bpb.de/themen/rechtsextremismus/infopool-rechtsextremismus/546159/ein-weg-aus-dem-rechtsextremismus/', 'bund', null, true, 'blind'),
  (7503, 9, 'Neue Straftatbestände gegen extremistische Propaganda (Bund)', 'Neue Straftatbestände können Werbung für Terror oder verfassungsfeindliche Ziele früher ahnden. Sie überschneiden sich teils mit geltendem Recht und müssen vor der Meinungsfreiheit bestehen. Zur Wirkung auf Gewalttaten gibt es keine Belege.', 'offen', null, 'bund', null, true, 'blind'),
  (7504, 9, 'Staatliche Förderung für extremistennahe Vereine ausschließen (Bund)', 'Die Maßnahme verhindert, dass extremistische Strukturen staatlich mitfinanziert werden. Auf Straftaten wirkt sie nur indirekt. Ein Ausschluss allein wegen einer Beobachtung oder wegen einzelner Mitglieder ist rechtlich angreifbar.', 'offen', null, 'bund', null, true, 'blind'),
  (7505, 9, 'Kriminalstatistik reformieren und Periodischen Sicherheitsbericht gesetzlich verankern (Bund)', 'Wissenschaftlich eingeordnete Lagebilder können verzerrte Wahrnehmungen korrigieren und sind leicht umsetzbar. Ob sie die öffentliche Wahrnehmung tatsächlich ändern, ist kaum untersucht.', 'offen', null, 'bund', null, true, 'blind'),
  (7506, 9, 'Sichtbare Polizeipräsenz und Kontrollen an Kriminalitätsschwerpunkten (Bund)', 'Studien zur gezielten Polizeipräsenz an Brennpunkten zeigen weniger Kriminalität ohne Verdrängung in andere Gebiete. Die meisten Orte liegen aber in der Zuständigkeit der Landespolizei, und Personal fehlt.', 'belegt', 'https://nij.ojp.gov/library/publications/hot-spots-policing-and-crime-reduction-update-ongoing-systematic-review-and', 'bund', null, true, 'blind'),
  (7507, 9, 'Flächendeckende Videoüberwachung und Gesichtserkennung im öffentlichen Raum ablehnen (Bund)', 'Die Ablehnung schützt Grundrechte, bringt die Sicherheit an unsicheren Orten aber nicht voran. Videoüberwachung senkt laut Meta-Analyse vor allem Eigentums- und Fahrzeugdelikte, kaum Gewalt; der Verzicht kostet daher wenig.', 'gemischt', 'https://www.ojp.gov/library/publications/cctv-surveillance-crime-prevention-40-year-systematic-review-meta-analysis', 'bund', null, true, 'blind'),
  (7626, 9, 'Gezielte Polizeipräsenz und Streifen an Kriminalitätsschwerpunkten wie Bahnhöfen und Parks (Land)', 'Studien zur gezielten Polizeipräsenz an Brennpunkten zeigen weniger Kriminalität ohne Verdrängung, teils mit Nutzen für das Umfeld. Die Landespolizei ist zuständig, doch Personal für dauerhafte Präsenz ist knapp.', 'belegt', 'https://www.ojp.gov/library/publications/hot-spots-policing-and-crime-reduction-update-ongoing-systematic-review-and', 'land', null, true, 'blind'),
  (7627, 9, 'Mehr sichtbare Polizeipräsenz und Streifen im öffentlichen Raum allgemein (Land)', 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'gemischt', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'land', null, true, 'blind'),
  (7628, 9, 'Mehr Sicherheitspersonal an Bahnhöfen, Haltestellen und im Nahverkehr (Land)', 'Ein Zufallsexperiment an 41 Bahnhöfen fand bei Streifen durch Sicherheitspersonal 16 % weniger Taten, bei Gewalt 31 % weniger. Das Personal kostet dauerhaft und muss mit den Verkehrsunternehmen vereinbart werden.', 'belegt', 'https://journals.plos.org/plosone/article?id=10.1371%2Fjournal.pone.0187392', 'land', null, true, 'blind'),
  (7629, 9, 'Bessere Beleuchtung und städtebauliche Kriminalprävention an Angsträumen (Land)', 'Eine Übersichtsstudie und ein Zufallsexperiment in New York zeigen weniger Kriminalität nach besserer Beleuchtung, dort nachts im Freien rund ein Drittel weniger schwere Taten. Umsetzen müssen meist die Kommunen, das Land kann fördern.', 'belegt', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/effects-improved-street-lighting-crime', 'land', null, true, 'blind'),
  (7630, 9, 'Videoüberwachung an kriminalitätsbelasteten Orten ausbauen (Land)', 'Videoüberwachung senkt Kriminalität laut Meta-Analyse moderat, vor allem Eigentumsdelikte auf Parkplätzen, kaum Gewalt. Aktiv beobachtete Kameras wirken stärker. Das Polizeirecht des Landes erlaubt den Ausbau an belasteten Orten.', 'belegt', 'https://www.ojp.gov/library/publications/cctv-surveillance-crime-prevention-40-year-systematic-review-meta-analysis', 'land', null, true, 'blind'),
  (7631, 9, 'Flächendeckende Videoüberwachung und biometrische Gesichtserkennung ablehnen (Land)', 'Die Ablehnung schützt Grundrechte, bringt die Sicherheit an unsicheren Orten aber nicht voran. Da Videoüberwachung Gewalt laut Meta-Analyse kaum senkt, kostet der Verzicht wenig.', 'gemischt', null, 'land', null, true, 'blind'),
  (7632, 9, 'Anlasslose Kontrollen und Sonderbefugnisse an kriminalitätsbelasteten Orten ausweiten (Land)', 'Die Evaluation der Leipziger Waffenverbotszone fand weniger bewaffnete Angriffe, aber kaum Wirkung auf andere Taten. Anlasslose Kontrollen können Vertrauen kosten. Das Land kann sie im Polizeigesetz regeln.', 'gemischt', 'https://medienservice.sachsen.de/medien/news/252888', 'land', null, true, 'blind'),
  (7633, 9, 'Waffenverbotszonen und anlasslose Kontrollen abschaffen oder eng begrenzen (Land)', 'Die Abschaffung beugt diskriminierenden Kontrollen vor, verzichtet aber auf ein Mittel, das in Leipzig bewaffnete Angriffe etwas senkte. Die Sicherheit an belasteten Orten verbessert sie nicht.', 'gemischt', null, 'land', null, true, 'blind'),
  (7634, 9, 'Aufsuchende Sozialarbeit, Drogenhilfe, Konsumräume und Parkläufer an belasteten Orten (Land)', 'Konsumräume und aufsuchende Hilfe verringern laut Evaluationen offenen Drogenkonsum und Szenebelastung; Diebstahl und Raub im Umfeld sinken aber nicht. Das Land kann solche Angebote mit den Kommunen rasch finanzieren.', 'gemischt', null, 'land', null, true, 'blind'),
  (7635, 9, 'Polizeipersonal aufstocken oder halten, Nachwuchsgewinnung und Bezahlung verbessern (Land)', 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'gemischt', null, 'land', null, true, 'blind'),
  (7636, 9, 'Ausstattung und Digitalisierung der Polizei, Entlastung von Verwaltungsarbeit (Land)', 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'offen', null, 'land', null, true, 'blind'),
  (7637, 9, 'Mehr Personal für Gerichte und Staatsanwaltschaften, Justizberufe attraktiver machen (Land)', 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'belegt', null, 'land', null, true, 'blind'),
  (7638, 9, 'Digitalisierung der Justiz und elektronische Akte (Land)', 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und die Einführung der E-Akte zieht sich seit Jahren.', 'offen', null, 'land', null, true, 'blind'),
  (7639, 9, 'Beschleunigte und vereinfachte Strafverfahren stärker nutzen, auch bei Jugendlichen (Land)', 'Eine Evaluation des Neuköllner Modells zeigt schnellere Verfahren in geeigneten Fällen; eine Wirkung auf spätere Straftaten ist nicht belegt. Die Verfahren gibt es schon, Länder können sie organisatorisch stärken.', 'gemischt', 'https://jugendsozialarbeit.news/evaluation_beschleunigtes_jugendverfahren/', 'land', null, true, 'blind'),
  (7640, 9, 'Häuser des Jugendrechts und behördenübergreifende Zusammenarbeit bei Jugendstraftaten (Land)', 'Evaluationen zeigen eine bessere Zusammenarbeit von Polizei, Justiz und Jugendhilfe, teils kürzere Verfahren und weniger Rückfälle; Vergleichsgruppen fehlen oft. Länder können solche Häuser selbst einrichten.', 'gemischt', 'https://www.iss-ffm.de/themen/armut-und-armutsfolgen/projekte/evaluation-der-haeuser-des-jugendrechts-in-niedersachsen', 'land', null, true, 'blind'),
  (7641, 9, 'Jugendstrafrecht verschärfen über den Bund: Strafmündigkeit senken, Heranwachsende, Warnschussarrest (Land)', 'Fachverbände sehen keine Belege für eine abschreckende Wirkung, und nach Arrest und Jugendstrafe sind Rückfallquoten hoch. Dafür spricht ein früheres Eingreifen bei Intensivtätern. Das Land kann nur über den Bundesrat werben.', 'belegt', 'https://jugendhilfeportal.de/artikel/stellungnahme-zur-forderung-der-senkung-des-strafmuendigkeitsalters-durch-cdu-generalsekretaer', 'land', null, true, 'blind'),
  (7642, 9, 'Gewaltprävention an Schulen, Jugend- und Schulsozialarbeit, Streetwork mit Präventionsauftrag (Land)', 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'gemischt', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'land', null, true, 'blind'),
  (7643, 9, 'Frauenhausplätze, Schutzwohnungen und Beratung ausbauen und dauerhaft finanzieren (Land)', 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'belegt', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'land', null, true, 'blind'),
  (7644, 9, 'Täterarbeit bei häuslicher Gewalt ausbauen, auch als verpflichtende Auflage (Land)', 'Eine Meta-Analyse findet nach längeren Täterprogrammen deutlich weniger amtlich erfasste Rückfälle, nach Angaben der Partnerinnen aber keinen Effekt; kurze Programme wirken nicht. Das Land kann Angebote fördern.', 'gemischt', 'https://journals.copmadrid.org/pi/art/pi2020a11', 'land', null, true, 'blind'),
  (7645, 9, 'Hochrisikomanagement, Gefährdungsanalyse und Fallkonferenzen bei häuslicher Gewalt (Land)', 'Fallkonferenzen und standardisierte Risikoeinschätzung wie in Großbritannien und Spanien sollen Hochrisikofälle früh erkennen; Berichte melden weniger Wiederholungstaten, aber auch Fehleinschätzungen. Das Land kann es selbst einführen.', 'gemischt', null, 'land', null, true, 'blind'),
  (7646, 9, 'Elektronische Fußfessel, Wegweisung, Kontakt- und Näherungsverbote bei häuslicher Gewalt (Land)', 'Überwachte Näherungsverbote nach spanischem Vorbild können Hochrisikofälle schützen. Die Geräte sind aber störanfällig, erreichen nur wenige Fälle und setzen eine Anzeige voraus. Länder können sie im Polizeirecht regeln.', 'gemischt', null, 'land', null, true, 'blind'),
  (7647, 9, 'Femizide einheitlich definieren und systematisch erfassen (Land)', 'Eine einheitliche Erfassung verbessert das Lagebild und kann Prävention gezielter machen. Sie verhindert selbst keine Taten, und zur Wirkung gibt es kaum Daten.', 'offen', null, 'land', null, true, 'blind'),
  (7648, 9, 'Landesaktionsplan oder Koordinierungsstelle gegen geschlechtsspezifische Gewalt (Land)', 'Ein Aktionsplan oder eine Koordinierungsstelle kann Zuständigkeiten klären und Lücken sichtbar machen. Ohne zusätzliche Mittel bleibt die Wirkung offen.', 'offen', null, 'land', null, true, 'blind'),
  (7649, 9, 'Spezialisierte Zuständigkeiten in der Justiz für geschlechtsspezifische und sexualisierte Gewalt (Land)', 'Spezialisierte Staatsanwälte und Kammern können Verfahren beschleunigen und Betroffene schonen. Belege für mehr Anzeigen oder Verurteilungen fehlen weitgehend.', 'offen', null, 'land', null, true, 'blind'),
  (7650, 9, 'Gewaltschutz vor Umgangsrecht gewalttätiger Elternteile über den Bund (Land)', 'Gewalt setzt sich nach Trennungen oft bei Umgangskontakten fort; ein Vorrang des Schutzes setzt dort an. Das Familienrecht regelt der Bund, das Land kann nur werben, und zur Wirkung gibt es kaum Daten.', 'offen', null, 'land', null, true, 'blind'),
  (7651, 9, 'Strafen für einzelne Delikte über den Bund verschärfen (Land)', 'Höhere Strafen benennen Unrecht klarer. Die Forschung zeigt aber übereinstimmend, dass vor allem das Entdeckungsrisiko abschreckt, kaum die Strafhöhe. Das Strafrecht ändert der Bund, das Land kann nur werben.', 'belegt', null, 'land', null, true, 'blind'),
  (7652, 9, 'Gewaltschutzambulanzen und vertrauliche Spurensicherung flächendeckend ausbauen (Land)', 'Vertrauliche Spurensicherung und Ambulanzen sichern Beweise, auch wenn Betroffene erst später anzeigen. Wie stark das Anzeigen und Verurteilungen erhöht, ist kaum untersucht. Das Land kann die Angebote ausbauen.', 'offen', null, 'land', null, true, 'blind'),
  (7653, 9, 'Herkunft von Tatverdächtigen in Statistiken, Lagebildern und Polizeimeldungen häufiger ausweisen (Land)', 'Mehr Angaben zur Staatsangehörigkeit sollen Transparenz schaffen. Ob das die verzerrte Wahrnehmung korrigiert oder verstärkt, ist offen; Medien nennen bei Gewalttaten schon heute fast nur ausländische Tatverdächtige.', 'offen', null, 'land', null, true, 'blind'),
  (7654, 9, 'Periodischer Sicherheitsbericht, Dunkelfeldbefragungen und wissenschaftliche Einordnung der Kriminalstatistik (Land)', 'Wissenschaftlich eingeordnete Lagebilder und Dunkelfeldbefragungen machen das tatsächliche Geschehen sichtbar und sind leicht umsetzbar. Ob sie die öffentliche Wahrnehmung ändern, ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (7655, 9, 'Vermögensabschöpfung und Finanzermittlungen gegen organisierte Kriminalität (Land)', 'Vermögensabschöpfung trifft kriminelle Strukturen finanziell und ist eine spürbare Tatfolge. Auf die Aufklärung alltäglicher Straftaten wirkt sie kaum, Wirkungsstudien fehlen.', 'offen', null, 'land', null, true, 'blind'),
  (7656, 9, 'Beweislastumkehr bei der Einziehung kriminellen Vermögens über den Bund (Land)', 'Eine leichtere Einziehung trifft kriminelle Strukturen finanziell, wirkt aber kaum auf alltägliche Taten. Die Beweislastumkehr regelt der Bund, und sie steht im Konflikt mit Unschuldsvermutung und Eigentumsschutz.', 'offen', null, 'land', null, true, 'blind'),
  (7657, 9, 'Spezialisierte Ermittlungsgruppen gegen organisierte Kriminalität (Land)', 'Dauerhafte Ermittlungsgruppen bündeln Wissen gegen organisierte Kriminalität. Auf die Aufklärung der vielen alltäglichen Taten wirken sie kaum, und Belege zur Wirkung fehlen.', 'offen', null, 'land', null, true, 'blind'),
  (7658, 9, 'Fahren ohne Fahrschein entkriminalisieren und Ersatzfreiheitsstrafe abschaffen über den Bund (Land)', 'Fahren ohne Fahrschein bindet viel Justizkapazität und führt oft zu Ersatzfreiheitsstrafen; eine Streichung entlastet. Schwere Taten werden dadurch nur indirekt schneller verfolgt, und das Land braucht den Bund.', 'belegt', 'https://www.drb.de/positionen/stellungnahmen/stellungnahme/news/14-2023', 'land', null, true, 'blind'),
  (7659, 9, 'Überwachungsbefugnisse und automatisierte Datenanalyse ablehnen oder begrenzen (Land)', 'Die Begrenzung schützt Grundrechte, bringt die Aufklärung aber nicht voran. Belege, dass automatisierte Analysen oder Staatstrojaner die Aufklärung messbar erhöhen, fehlen, der Verlust wäre also gering.', 'gemischt', null, 'land', null, true, 'blind'),
  (7660, 9, 'Quick-Freeze-Verfahren statt Vorratsdatenspeicherung über den Bund (Land)', 'Quick Freeze ist grundrechtsschonend, greift aber nur bei Daten, die bei der Anordnung noch vorhanden sind. Die Strafprozessordnung regelt der Bund, das Land kann nur werben.', 'gemischt', null, 'land', null, true, 'blind'),
  (7661, 9, 'KI-gestützte Datenanalyse, Auswertesoftware und behördenübergreifendes Datenmanagement ausbauen (Land)', 'Automatisierte Analysen und Auswertesoftware können Ermittlungen beschleunigen. Unabhängige Belege für höhere Aufklärungsquoten fehlen, und das Bundesverfassungsgericht hat enge Grenzen gesetzt.', 'offen', null, 'land', null, true, 'blind'),
  (7932, 18, 'CO2-Bepreisung bzw. Emissionshandel für Verkehr und Gebäude stärken (Bund)', 'CO2-Preise senken Emissionen nachweislich (Metaanalyse: im Mittel rund 10 %). Auf Hitze in Deutschland wirkt nationaler Klimaschutz aber nur als kleiner Beitrag zum globalen Klimaschutz und mit großer Verzögerung.', 'belegt', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11099057/', 'bund', null, true, 'blind'),
  (7933, 18, 'Verbindliche Sektorziele und Nachsteuerungspflicht im Klimaschutzgesetz (Bund)', 'Verbindliche Sektorziele erhöhen den Druck zum Nachsteuern und sind per Gesetzesänderung umsetzbar; ihre eigene Wirkung ist kaum belegt, und auf die Hitze in Deutschland wirkt nationaler Klimaschutz nur langfristig und gering.', 'offen', null, 'bund', null, true, 'blind'),
  (7934, 18, 'Ausbau erneuerbarer Strom- und Wärmeversorgung fördern (Bund)', 'Erneuerbare vermieden 2024 laut UBA rund 259 Mio. t CO2-Äquivalente; Förderprogramme bestehen. Auf Hitzetage in Deutschland wirkt das nur als kleiner Teil des globalen Klimaschutzes und mit Verzögerung.', 'belegt', 'https://www.umweltbundesamt.de/publikationen/emissionsbilanz-erneuerbarer-energietrager-2024', 'bund', null, true, 'blind'),
  (7935, 18, 'Abscheidung und Speicherung von CO2 (CCS/CCU) ermöglichen und fördern (Bund)', 'Seit Ende 2025 ist kommerzielles CCS rechtlich möglich; es kann schwer vermeidbare Industrieemissionen senken. Dagegen: Infrastruktur braucht 7 bis 10 Jahre, Kosten und Umfang sind unsicher; Wirkung auf Hitze gering.', 'gemischt', 'https://www.bundesregierung.de/breg-de/aktuelles/speicherung-von-kohlendioxid-2376946', 'bund', null, true, 'blind'),
  (7936, 18, 'Kohleausstieg aussetzen oder Abschaltung von Kohlekraftwerken aufschieben (Bund)', 'Längerer Kohlebetrieb erhöht die Emissionen gegenüber einem Ausstieg (Studien: deutliche Minderung durch Ausstieg) und hilft nicht gegen Hitze; per Gesetz änderbar, aber durch CO2-Preise im EU-Emissionshandel wirtschaftlich fraglich.', 'belegt', 'https://www.ewi.uni-koeln.de/en/news/neue-ewi-studie-kohleausstieg-ermoeglicht-erreichung-der-klimaziele-2030/', 'bund', null, true, 'blind'),
  (7937, 18, 'Nationalen CO2-Preis abschaffen (Bund)', 'Entfernt ein nachweislich emissionsmindernd wirkendes Instrument und hilft nicht gegen Hitze. National möglich, ab 2028 greift für Verkehr und Gebäude aber ohnehin der EU-Emissionshandel.', 'belegt', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11099057/', 'bund', null, true, 'blind'),
  (7938, 18, 'CO2-Flottenvorgaben für Neuwagen (Verbrenner-Aus 2035) aufheben (Bund)', 'Lockert eine Emissionsvorgabe und setzt an keiner Ursache im Sinne des Ziels an. Die Vorgabe ist EU-Recht; Deutschland kann sie nicht allein aufheben, sondern nur im EU-Verfahren darauf hinwirken.', 'offen', null, 'bund', null, true, 'blind'),
  (7939, 18, 'Heizungsvorgaben im Gebäudeenergiegesetz abschaffen (Bund)', 'Lockert eine Vorgabe zur Emissionsminderung bei Heizungen und hilft nicht gegen Hitze oder Unwetterschäden. Per Bundesgesetz änderbar, EU-Gebäuderichtlinie setzt aber Grenzen.', 'offen', null, 'bund', null, true, 'blind'),
  (7940, 18, 'Bundesförderung für Stadtgrün, Entsiegelung und hitzeangepasste Städte (Bund)', 'Parks und Bäume kühlen nachweislich (große Parks 1 bis 2 °C im Umfeld); der Bund fördert Städtebau bereits. Dagegen: Wirkung bleibt lokal und hängt von Umsetzung in den Kommunen ab.', 'belegt', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'bund', null, true, 'blind'),
  (7941, 18, 'Allgemeine Zusage zu Begrünung und Entsiegelung ohne konkretes Instrument (Bund)', 'Begrünung und Entsiegelung wirken nachweislich gegen Hitze und Abfluss; die Zusage nennt aber weder Instrument noch Mittel, daher ist kaum eine Verbesserung absehbar.', 'belegt', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'bund', null, true, 'blind'),
  (7942, 18, 'Bundesmittel für Hochwasserschutz: Deiche, Rückhalteräume und Auen (Bund)', 'Rückhalteräume und Auen dämpfen Hochwasserscheitel nachweislich, der Bund fördert Hochwasserschutz bereits mit. Dagegen: Deiche verlagern Risiken teils flussabwärts und ändern das Bauen in Überschwemmungsgebieten nicht.', 'belegt', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'bund', null, true, 'blind')
